-- ═══════════════════════════════════════════════════════════════════════
-- Flashcards: Mathematics AQA (7357) and Further Mathematics Edexcel (9FM0)
-- 2026-10-10 — bug G-12 ("Maths AQA and Further Maths Edexcel have no
-- flashcards at all").
--
-- Paste into the Supabase SQL editor. Idempotent — safe to re-run.
--
-- WHY. Cards live in the flashcards table, not in code. Both decks already
-- have their topic lists in flashcards-config.js ('Mathematics|AQA' and
-- 'Further Mathematics|Edexcel', A-level), so the pages list the topics,
-- but no system cards were ever inserted for them. This inserts full decks:
--   Mathematics|AQA              12 topics, 504 cards
--     1.1: 37, 1.2: 39, 1.3: 37, 1.4: 36, 1.5: 39, 1.6: 37, 1.7: 38, 1.8: 39, 1.9: 36, 1.10: 35, 2.1: 70, 2.2: 61
--   Further Mathematics|Edexcel  17 topics, 587 cards
--     CP1.1: 35, CP1.2: 35, CP1.3: 34, CP1.4: 35, CP1.5: 33, CP1.6: 35, CP1.7: 35, CP1.8: 34, CP1.9: 35, CP2.1: 35, CP2.2: 35, CP2.3: 36, CP2.4: 32, CP2.5: 34, CP2.6: 35, CP2.7: 34, CP2.8: 35
--
-- Each deck is the shared 30-per-topic set from flashcards/topup/src (same
-- fronts as flashcards/topup/maths-aqa-alevel.sql and fm-edexcel-alevel.sql)
-- plus board-specific cards: AQA 7357 proof methods, first-principles trig,
-- and the AQA statistics and mechanics content (Statistics and Mechanics are
-- single topics in the config, so they carry more cards), and Edexcel Core
-- Pure worked examples. Maths notation is plain Unicode (x², √, π, ∫, Σ, θ)
-- like every other maths deck — the card renderer does not run LaTeX.
--
-- SAFE WHATEVER IS LIVE. The INSERTs skip any card whose front is already in
-- that topic and continue card_order after the topic's current max, so
-- running this twice — or before or after flashcards/topup/paste/4-maths.sql
-- or 5-further-maths.sql — never duplicates a card. Those top-up files cap a
-- topic at 30, so once this has run they insert nothing for these decks.
--
-- CHECK afterwards:
--   select subject, exam_board, topic_id, count(*) from flashcards
--   where (subject, exam_board) in (('Mathematics','AQA'),('Further Mathematics','Edexcel'))
--     and level = 'alevel'
--   group by 1, 2, 3 order by 1, 2, 3;
-- ═══════════════════════════════════════════════════════════════════════

BEGIN;

ALTER TABLE flashcards ADD COLUMN IF NOT EXISTS level TEXT DEFAULT 'alevel'
  CHECK (level IN ('gcse','as','alevel'));

-- ═══════════════════════════════════════════════════════════════════════
-- MATHEMATICS — AQA A-LEVEL (7357)
-- ═══════════════════════════════════════════════════════════════════════

WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What is proof by deduction?', 'Proceeding from given assumptions through a series of logical steps to a conclusion.', 1),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What is proof by exhaustion?', 'Establishing a result by checking every case of a finite set of cases, having first shown the cases cover all possibilities.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What is proof by contradiction?', 'Assume the statement is false, reason correctly from that assumption, and derive an impossibility. The assumption must therefore be wrong.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'How do you disprove a general statement?', 'Give a single counter-example — one case for which the statement fails. One example never proves a general statement, but one counter-example always disproves it.', 4),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What does P ⇒ Q mean, and how does it differ from P ⇔ Q?', 'P ⇒ Q means P implies Q. P ⇔ Q means each implies the other. Writing ⇔ requires both directions to hold.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What is the contrapositive of ''if P then Q'', and why is it useful?', '''If not Q then not P''. It is logically equivalent to the original, so proving it proves the original — often easier than a direct argument.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What is the converse of ''if P then Q''? Is it always true?', '''If Q then P''. It is a different statement and need not be true, confusing the two is a common error.', 7),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Give the counter-example that disproves ''every prime is odd''.', '2 is prime and even.', 8),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Give the counter-example that disproves ''n² − n + 41 is prime for every positive integer n''.', 'n = 41, where the expression equals 41², divisible by 41. It does give primes for n = 1 to 40, which is why testing values is not proof.', 9),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Outline the proof that √2 is irrational.', 'Assume √2 = p/q in lowest terms. Then p² = 2q², so p is even, writing p = 2k gives q² = 2k², so q is even. Both even contradicts lowest terms.', 10),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Why is ''in its lowest terms'' essential to the √2 proof?', 'It is the assumption the final contradiction violates. Without it, showing p and q are both even contradicts nothing and the proof fails.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Why can the √2 argument not be copied to prove √4 irrational?', 'It would need ''p² divisible by 4 ⇒ p divisible by 4'', which is false (take p = 2). The proof breaks exactly where it must, since √4 = 2 is rational.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Outline Euclid''s proof that there are infinitely many primes.', 'Assume a finite list p₁…pₙ and form N = p₁p₂⋯pₙ + 1. No prime in the list divides N, so N is prime or has a prime factor outside the list — contradicting completeness.', 13),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'In Euclid''s proof, must N = p₁⋯pₙ + 1 be prime?', 'No. It need only have no factor in the list. With 2,3,5,7,11,13 you get 30031 = 59 × 509 — composite, but both factors lie outside the list.', 14),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What is the negation of ''all swans are white''?', '''There exists a swan that is not white.'' It is not ''no swans are white'', which is a much stronger claim.', 15),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What is a conjecture?', 'A statement believed to be true but not yet proved.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What does "if and only if" require you to prove?', 'Both directions: P ⇒ Q and Q ⇒ P.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Prove that the sum of two odd numbers is even.', 'Let the odd numbers be 2m + 1 and 2n + 1. Their sum is 2m + 2n + 2 = 2(m + n + 1), which is even.', 18),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'How do you represent an even and an odd integer algebraically?', 'Even: 2n. Odd: 2n + 1 (or 2n − 1), where n is an integer.', 19),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'How do you represent consecutive integers?', 'n, n + 1, n + 2, … where n is an integer.', 20),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Prove that the square of any odd number is odd.', '(2n + 1)² = 4n² + 4n + 1 = 2(2n² + 2n) + 1, which is odd.', 21),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Prove that n³ − n is always divisible by 6.', 'n³ − n = (n − 1)n(n + 1), the product of three consecutive integers. One is a multiple of 3 and at least one is even, so the product is divisible by 6.', 22),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What is the first step in a proof by contradiction?', 'Assume the negation of the statement you want to prove.', 23),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'How do you prove there is no largest even number?', 'Assume N is the largest even number. Then N + 2 is even and larger, a contradiction.', 24),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'When is proof by exhaustion practical?', 'When there is a small finite number of cases to check, e.g. all integers from 1 to 10, or cases such as n odd and n even.', 25),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What does ∴ mean in a proof?', '"Therefore".', 26),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What does the symbol ∈ mean?', '"Is an element of", e.g. n ∈ ℤ means n is an integer.', 27),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'What do ℕ, ℤ, ℚ and ℝ represent?', 'Natural numbers, integers, rational numbers and real numbers respectively.', 28),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Why is a single example not a proof of a general statement?', 'It only shows the statement holds in that case; a proof must cover every case.', 29),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Prove that the product of two consecutive integers is even.', 'Consider n(n + 1). One of n and n + 1 is even, so the product has a factor of 2 and is even.', 30),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Which methods of proof does AQA A-level Maths (7357) require?', 'Proof by deduction, proof by exhaustion, disproof by counter-example and proof by contradiction — including the irrationality of √2 and the infinity of primes. Proof by induction is Further Maths only.', 31),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Prove that n² + 3n + 1 is odd for every integer n.', 'n² + 3n = n(n + 3). If n is even the product is even, if n is odd then n + 3 is even. Either way n(n + 3) is even, so n² + 3n + 1 is odd.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Prove that if n² is even then n is even.', 'Prove the contrapositive. If n is odd, n = 2k + 1 and n² = 4k² + 4k + 1 = 2(2k² + 2k) + 1, which is odd. So n odd ⇒ n² odd, hence n² even ⇒ n even.', 33),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Prove that log₂3 is irrational.', 'Assume log₂3 = p/q with p, q positive integers. Then 2^(p/q) = 3, so 2ᵖ = 3^q. The left side is even and the right side is odd — a contradiction.', 34),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Prove that the sum of a rational number and an irrational number is irrational.', 'Suppose r is rational, x irrational and r + x = s is rational. Then x = s − r is a difference of rationals, so rational — a contradiction.', 35),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Disprove: ''if a > b then a² > b²''.', 'Counter-example: a = 1, b = −2. Then a > b but a² = 1 < 4 = b².', 36),
  ('Mathematics', 'AQA', 'alevel', '1.1', 'Proof', 'Prove by exhaustion that no square number ends in the digit 7.', 'The last digit of n² depends only on the last digit of n. Squaring 0 to 9 gives last digits 0, 1, 4, 9, 6, 5, 6, 9, 4, 1 — never 7.', 37),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'How do you simplify a surd such as √50?', 'Extract the largest square factor: √50 = √(25 × 2) = 5√2.', 1),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'How do you rationalise a denominator of the form a + √b?', 'Multiply numerator and denominator by the conjugate a − √b, using the difference of two squares to clear the surd.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Is √(a + b) equal to √a + √b?', 'No. The product rule holds but the sum rule does not: √(9 + 16) = 5 while √9 + √16 = 7.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'State the laws of indices for multiplication, division and powers.', 'xᵃ × xᵇ = x^(a+b), xᵃ ÷ xᵇ = x^(a−b). (xᵃ)ᵇ = x^(ab).', 4),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'What are x⁰, x^(−a) and x^(m/n)?', 'x⁰ = 1 for x ≠ 0, x^(−a) = 1/xᵃ, x^(m/n) = (ⁿ√x)^m — take the root first to keep the numbers small.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'What is the discriminant, and what do its three cases tell you?', 'b² − 4ac. Positive: two distinct real roots. Zero: one repeated root. Negative: no real roots.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'What is the difference between ''two distinct real roots'' and ''real roots''?', 'Distinct requires b² − 4ac > 0, ''real roots'' usually allows the repeated case, so b² − 4ac ≥ 0. The wording decides < or ≤ in the answer.', 7),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'What is the condition for a line to be tangent to a curve?', 'Substitute the line into the curve and set the discriminant of the resulting quadratic to zero.', 8),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'How do you complete the square for x² + bx + c?', 'Write (x + b/2)² and subtract (b/2)², then add c. For x² + 6x + 2 this gives (x + 3)² − 7, so the minimum is at (−3, −7).', 9),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'How do you solve one linear and one quadratic simultaneous equation?', 'Always substitute the linear equation into the quadratic, then substitute the roots back into the linear equation and pair the values correctly.', 10),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'How do you solve a quadratic inequality such as x² − 4x − 5 > 0?', 'Factorise to find the critical values, then read the sign from the parabola''s shape. Upward parabola: positive outside the roots, so x < −1 or x > 5.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Why can''t you multiply an inequality through by (x − 3)?', 'Its sign is unknown, so the inequality may or may not reverse. Instead collect over a common denominator, or multiply by the square (x − 3)², which is always positive.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'When do two solution intervals need ''or'' rather than ''and''?', 'Always, for two separate intervals. ''x < −1 and x > 5'' describes no numbers at all, the union needs ''or''.', 13),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Write the four proportion relationships and their equations.', 'y ∝ x gives y = kx, y ∝ 1/x gives y = k/x, y ∝ xⁿ gives y = kxⁿ, y ∝ 1/x² gives y = k/x².', 14),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'What is the commonest error with repeated factors in partial fractions?', 'Omitting the A/(x+a) term and using only B/(x+a)². The system then has no solution.', 15),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Simplify √12 + √27.', '2√3 + 3√3 = 5√3.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'State the factor theorem.', 'If f(a) = 0 then (x − a) is a factor of f(x), and conversely.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'State the remainder theorem.', 'The remainder when f(x) is divided by (x − a) is f(a). A remainder of zero means (x − a) is a factor.', 18),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'To test whether (x + 3) is a factor, which value do you substitute?', 'x = −3, since (x + 3) = (x − (−3)). Substituting +3 is the standard sign error.', 19),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'When hunting for a first factor of a cubic, which values should you test?', 'The divisors of the constant term. For a constant of 6, test ±1, ±2, ±3, ±6.', 20),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'What is the domain and what is the range of a function?', 'The domain is the set of permitted inputs, the range is the set of outputs the function actually takes.', 21),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'What are the two usual causes of a restricted domain?', 'You cannot divide by zero, and you cannot take the square root of a negative number.', 22),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'How do you find the range of a quadratic?', 'Complete the square. For f(x) = x² − 4x + 7 = (x − 2)² + 3, the range is f(x) ≥ 3.', 23),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'What does fg(x) mean?', 'f(g(x)) — apply g first, then f. The inner function is the one written next to the x.', 24),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Is composition of functions commutative?', 'No. With f(x) = 2x + 3 and g(x) = x², fg(x) = 2x² + 3 but gf(x) = (2x + 3)².', 25),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'When does an inverse function exist?', 'Only when the function is one-to-one. A many-to-one function such as x² needs its domain restricted first.', 26),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'How do you find an inverse function?', 'Write y = f(x), rearrange to make x the subject, then swap the letters. Use the given domain to choose the sign of any square root.', 27),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'How are the graphs of f and f⁻¹ related?', 'Each is the reflection of the other in the line y = x. Domain and range swap, and for an INCREASING function any intersection lies on y = x.', 28),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Define |x| as a piecewise function.', '|x| = x for x ≥ 0, and |x| = −x for x < 0. The graph is a V with vertex at the origin.', 29),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'How do you obtain y = |f(x)| from y = f(x)?', 'Reflect the parts below the x-axis up into it, leaving the rest unchanged. It acts on the OUTPUT.', 30),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Describe the transformations y = f(x + a), y = f(x) + a, y = af(x) and y = f(ax).', 'f(x + a): translation by a units in the negative x-direction. f(x) + a: translation a units up. af(x): stretch parallel to the y-axis, scale factor a. f(ax): stretch parallel to the x-axis, scale factor 1/a.', 31),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Solve |2x − 1| = x + 4.', '2x − 1 = x + 4 gives x = 5, and −(2x − 1) = x + 4 gives x = −1. Both check: |9| = 9 and |−3| = 3.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Solve |x − 3| < 2.', '−2 < x − 3 < 2, so 1 < x < 5.', 33),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Express (5x + 1)/((x − 1)(x + 2)) in partial fractions.', '5x + 1 = A(x + 2) + B(x − 1). x = 1 gives A = 2, x = −2 gives B = 3. So 2/(x − 1) + 3/(x + 2).', 34),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'What partial fraction form does AQA use for (px + q)/((x − a)(x − b)²)?', 'A/(x − a) + B/(x − b) + C/(x − b)². AQA limits denominators to linear and squared linear factors, with at most three terms.', 35),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Fully factorise x³ − 2x² − 5x + 6.', 'f(1) = 0, so (x − 1) is a factor. Dividing gives x² − x − 6, so x³ − 2x² − 5x + 6 = (x − 1)(x − 3)(x + 2).', 36),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Simplify (x² − 9)/(x² + x − 6).', '(x − 3)(x + 3)/((x + 3)(x − 2)) = (x − 3)/(x − 2), for x ≠ −3.', 37),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', '(x − 2) is a factor of x³ + ax² − 4. Find a.', 'f(2) = 8 + 4a − 4 = 0, so a = −1.', 38),
  ('Mathematics', 'AQA', 'alevel', '1.2', 'Algebra & Functions', 'Describe the graph of y = k/x² for k > 0.', 'Two branches, both above the x-axis, symmetrical about the y-axis, with asymptotes x = 0 and y = 0.', 39),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Write down the gradient, midpoint and distance formulae.', 'Gradient (y₂ − y₁)/(x₂ − x₁), midpoint ((x₁+x₂)/2, (y₁+y₂)/2), distance √((x₂−x₁)² + (y₂−y₁)²).', 1),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What is the relationship between perpendicular gradients?', 'Their product is −1, so one is the negative reciprocal of the other. The rule fails for a vertical line, whose gradient is undefined.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How do you show three points are collinear?', 'Show the gradient between successive pairs is equal, and note they share a common point.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Write down the equation of a circle with centre (a, b) and radius r.', '(x − a)² + (y − b)² = r². Note the signs: centre (2, −3) gives (x − 2)² + (y + 3)².', 4),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How do you find the centre and radius from x² + y² + 2gx + 2fy + c = 0?', 'Complete the square in both x and y. The right-hand side is then r², so remember to take the square root.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What is the commonest error when reading a circle equation?', 'Quoting r² as the radius. From (x − 3)² + (y + 2)² = 25 the radius is 5, not 25.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How do you find a circle''s equation from the endpoints of a diameter?', 'The centre is the midpoint, the radius is half the distance between the endpoints.', 7),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How do you tell whether a point is inside, on, or outside a circle?', 'Substitute the coordinates and compare with r². Greater than r² means outside, less means inside.', 8),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How do you find the equation of a tangent to a circle at a given point?', 'Find the gradient of the radius to that point, take its negative reciprocal for the tangent, then use the point-gradient form.', 9),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How do you find how many times a line meets a circle?', 'Substitute the line into the circle and look at the discriminant of the resulting quadratic: two roots, one (tangent), or none.', 10),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What are parametric equations?', 'x and y are each given as functions of a third variable, the parameter. Each parameter value gives one point on the curve.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Why are parametric equations useful?', 'They describe curves that cannot be written as y = f(x), such as a full circle, which fails the one-output-per-input test.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How do you convert parametric equations to Cartesian form?', 'Eliminate the parameter. Rearrange the SIMPLER equation for the parameter, or use sin²θ + cos²θ = 1 for trigonometric parameters.', 13),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What is dy/dx for a parametric curve?', 'dy/dx = (dy/dt) ÷ (dx/dt). Getting the fraction the wrong way up is a standard error.', 14),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Write down the parametric equations of a circle.', 'x = a + r cos θ and y = b + r sin θ, for centre (a, b) and radius r. Eliminating θ with cos²θ + sin²θ = 1 returns the Cartesian form.', 15),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Find the equation of the line through (1, 2) with gradient 3.', 'y − 2 = 3(x − 1), so y = 3x − 1.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What is the gradient of the line 2x + 3y = 6?', 'Rearrange to y = −2x/3 + 2, so gradient = −2/3.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Find the equation of the perpendicular bisector of A(0, 0) and B(4, 2).', 'Midpoint (2, 1); gradient AB = 1/2, so perpendicular gradient = −2. y − 1 = −2(x − 2), so y = −2x + 5.', 18),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What is the distance between (1, 2) and (4, 6)?', '√((4 − 1)² + (6 − 2)²) = √(9 + 16) = 5.', 19),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Find the centre and radius of x² + y² − 4x + 6y − 12 = 0.', '(x − 2)² + (y + 3)² = 25: centre (2, −3), radius 5.', 20),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What does the angle in a semicircle theorem state?', 'The angle subtended at the circumference by a diameter is a right angle.', 21),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What does the perpendicular from the centre to a chord do?', 'It bisects the chord.', 22),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What is the relationship between a tangent and a radius?', 'A tangent is perpendicular to the radius at the point of contact.', 23),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How do you find the equation of a circle through three points?', 'Find the perpendicular bisectors of two chords; they intersect at the centre. Then find the radius.', 24),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Convert x = t², y = 2t into Cartesian form.', 't = y/2, so x = y²/4, i.e. y² = 4x.', 25),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Find dy/dx for x = t², y = t³.', 'dy/dx = (3t²)/(2t) = 3t/2.', 26),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What is the parametric form of the circle (x − a)² + (y − b)² = r²?', 'x = a + r cos θ, y = b + r sin θ.', 27),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How do you find where a parametric curve meets the x-axis?', 'Set y = 0, solve for t, then substitute into x.', 28),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'What does it mean if a line meets a circle at exactly one point?', 'The line is a tangent to the circle (the discriminant is zero).', 29),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Find the equation of the tangent to x² + y² = 25 at (3, 4).', 'The radius has gradient 4/3, so the tangent has gradient −3/4: y − 4 = −3/4(x − 3), i.e. 3x + 4y = 25.', 30),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Convert x = 2 cos θ, y = 3 sin θ to Cartesian form.', 'cos θ = x/2 and sin θ = y/3, so x²/4 + y²/9 = 1 (an ellipse).', 31),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Convert x = 1/t, y = t + 1 to Cartesian form.', 't = 1/x, so y = 1/x + 1.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Find the gradient of x = 3t², y = 6t at t = 2.', 'dy/dx = 6 ÷ 6t = 1/t, which is 1/2 at t = 2.', 33),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'The line y = 2x + k is a tangent to x² + y² = 5. Find k.', 'x² + (2x + k)² = 5 gives 5x² + 4kx + k² − 5 = 0. Discriminant 16k² − 20(k² − 5) = 100 − 4k² = 0, so k = ±5.', 34),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'Show that the circles (x − 1)² + (y − 2)² = 4 and (x − 4)² + (y − 6)² = 9 touch.', 'The centres are 5 apart, and 5 = 2 + 3, the sum of the radii, so they touch externally.', 35),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How can parametric equations model the path of a projectile?', 'x = (u cos θ)t and y = (u sin θ)t − ½gt², with time t as the parameter. Eliminating t gives the Cartesian trajectory, a parabola.', 36),
  ('Mathematics', 'AQA', 'alevel', '1.3', 'Coordinate Geometry', 'How is ax + by + c = 0 form usually required in exam answers?', 'With a, b and c integers. Multiply out fractions after finding the line, e.g. y = −(2/3)x + 4 becomes 2x + 3y − 12 = 0.', 37),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Write down the nth term and sum formulae for an arithmetic sequence.', 'uₙ = a + (n − 1)d. Sₙ = (n/2)(2a + (n − 1)d), or (n/2)(a + l) using the last term.', 1),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Write down the nth term and sum formulae for a geometric sequence.', 'uₙ = arⁿ⁻¹. Sₙ = a(1 − rⁿ)/(1 − r) for r ≠ 1.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'When does a geometric series converge, and what is its sum to infinity?', 'It converges if and only if |r| < 1, and then S∞ = a/(1 − r). Always state the condition.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What happens if you use the sum-to-infinity formula when |r| ≥ 1?', 'It produces a plausible-looking number that is meaningless, because the series diverges.', 4),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is a recurrence relation?', 'A rule defining each term from the previous one, together with a starting value — for example u₍ₙ₊₁₎ = uₙ + 3 with u₁ = 2.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'How do you find the limit of a convergent recurrence relation?', 'Replace both u₍ₙ₊₁₎ and uₙ by L and solve for L, rejecting any root inconsistent with the sequence.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Write the binomial expansion of (1 + x)ⁿ for a positive integer n.', '1 + nx + [n(n−1)/2!]x² + [n(n−1)(n−2)/3!]x³ + … It terminates, giving exactly n + 1 terms.', 7),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is the standard error when expanding (1 + 2x)⁵?', 'Forgetting to raise the coefficient too: (2x)³ = 8x³, not 2x³.', 8),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'How do you find a particular coefficient in (a + b)ⁿ?', 'Use the term ⁿCᵣ a^(n−r) b^r, choosing r to give the required power.', 9),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What changes when the binomial index is negative or fractional?', 'The expansion no longer terminates — it becomes an infinite series — and it is valid only for |x| < 1.', 10),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is the validity condition for expanding (1 + ax)ⁿ with non-integer n?', '|ax| < 1, that is |x| < 1/|a|. It is NOT |x| < 1 whenever there is a coefficient on x.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Expand (1 + x)^(1/2) as far as the term in x².', '1 + x/2 − x²/8.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'How do you expand √(4 + x) using the binomial series?', 'Factorise first: √(4 + x) = 2(1 + x/4)^(1/2). The series cannot be applied to a bracket not starting with 1.', 13),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'How do you find the nth term given the sum of the first n terms?', 'uₙ = Sₙ − S₍ₙ₋₁₎. If Sₙ = n² then uₙ = n² − (n − 1)² = 2n − 1.', 14),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What are Σ from k=1 to n of k, and of (2k − 1)?', 'n(n + 1)/2 and n² respectively.', 15),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is the commonest confusion in sequences questions?', 'Mixing up uₙ (a single term) with Sₙ (a running total). Read the question twice.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Find the 10th term of the arithmetic sequence 3, 7, 11, …', 'a = 3, d = 4: u₁₀ = 3 + 9 × 4 = 39.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Find the sum of the first 20 terms of 3, 7, 11, …', 'S₂₀ = 20/2 × (2 × 3 + 19 × 4) = 10 × 82 = 820.', 18),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Find the sum to infinity of 8 + 4 + 2 + …', 'a = 8, r = 1/2: S∞ = 8/(1 − 1/2) = 16.', 19),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is a periodic sequence?', 'A sequence that repeats after a fixed number of terms, e.g. 1, −1, 1, −1, …', 20),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is an increasing sequence?', 'Each term is larger than the previous one: uₙ₊₁ > uₙ for all n.', 21),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is a divergent sequence?', 'A sequence that doesn''t tend to a finite limit.', 22),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is sigma notation?', 'A shorthand for sums: Σ from r=1 to n of f(r) means f(1) + f(2) + … + f(n).', 23),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is ⁿCᵣ?', 'The number of ways of choosing r items from n: n!/(r!(n − r)!).', 24),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Find the coefficient of x³ in (2 + x)⁵.', '⁵C₃ × 2² × x³ = 10 × 4 = 40.', 25),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Expand (1 − x)⁻¹ up to x³.', '1 + x + x² + x³, valid for |x| < 1.', 26),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Expand (1 + 2x)⁻² up to x².', '1 − 4x + 12x², valid for |x| < 1/2.', 27),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is Pascal''s triangle used for?', 'To find binomial coefficients for small positive integer powers.', 28),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'What is n! ?', 'n × (n − 1) × … × 2 × 1, with 0! = 1.', 29),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'How do you find the number of terms in an arithmetic sequence?', 'Use uₙ = a + (n − 1)d, set it equal to the last term and solve for n.', 30),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Find the sum of the multiples of 3 from 3 to 99.', 'An arithmetic series with 33 terms: S = 33/2 × (3 + 99) = 1683.', 31),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'A geometric sequence has second term 6 and fifth term 162. Find a and r.', 'ar = 6 and ar⁴ = 162, so r³ = 27, r = 3 and a = 2.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Find the least n for which 2 + 6 + 18 + … to n terms exceeds 1 000 000.', 'Sₙ = 2(3ⁿ − 1)/2 = 3ⁿ − 1 > 10⁶, so n > log(1 000 001)/log 3 ≈ 12.6. The least n is 13.', 33),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Expand (2 − x)⁻¹ up to x², stating validity.', '½(1 − x/2)⁻¹ = ½ + x/4 + x²/8, valid for |x| < 2.', 34),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Expand (1 + x)/(1 − 2x) up to x².', '(1 + x)(1 + 2x + 4x² + …) = 1 + 3x + 6x² + …, valid for |x| < ½.', 35),
  ('Mathematics', 'AQA', 'alevel', '1.4', 'Sequences & Series', 'Savings of £500 in year 1 rise by £50 each year. Find the total after 10 years.', 'Arithmetic series: S₁₀ = 10/2 × (2 × 500 + 9 × 50) = 5 × 1450 = £7250.', 36),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What is a radian, and how does it relate to degrees?', 'The angle subtended at the centre by an arc equal in length to the radius. π radians = 180°.', 1),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Write down the arc length and sector area formulae.', 's = rθ and A = ½r²θ, both requiring θ in RADIANS. Using degrees gives an answer wrong by a factor of about 57.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'State the sine rule, the cosine rule and the triangle area formula.', 'a/sin A = b/sin B = c/sin C, a² = b² + c² − 2bc cos A. Area = ½ab sin C.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'When do you use the cosine rule rather than the sine rule?', 'With three sides, or two sides and the angle between them. Otherwise use the sine rule.', 4),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What is the ambiguous case of the sine rule?', 'Given two sides and a non-included angle, sin θ = k has two solutions in 0° to 180°: θ and 180° − θ. Both must be checked.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Give the exact values of sin, cos and tan at 30°, 45° and 60°.', 'sin: ½, √2/2, √3/2.  cos: √3/2, √2/2, ½.  tan: 1/√3, 1, √3.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'How do you find the second solution of sin x = k, cos x = k and tan x = k?', 'For sin: π − x. For cos: 2π − x. For tan: x + π.', 7),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'How do you solve an equation such as sin 2x = k over 0° ≤ x < 360°?', 'Widen the range FIRST: 2x runs over 0° to 720°. Solve there, then halve every answer. Halving first loses half the solutions.', 8),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Define sec, cosec and cot.', 'sec θ = 1/cos θ, cosec θ = 1/sin θ, cot θ = 1/tan θ. Look at the third letter: se-c goes with c-os.', 9),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'State the two identities derived from sin²θ + cos²θ = 1.', '1 + tan²θ = sec²θ (divide by cos²θ), 1 + cot²θ = cosec²θ (divide by sin²θ).', 10),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Write down the compound angle formulae for sin(A ± B) and cos(A ± B).', 'sin(A ± B) = sin A cos B ± cos A sin B, cos(A ± B) = cos A cos B ∓ sin A sin B — note the sign flip.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Write down the three forms of cos 2θ.', 'cos²θ − sin²θ, 2cos²θ − 1, 1 − 2sin²θ. Choose the form matching the other function in the equation.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What are sin 2θ and tan 2θ?', 'sin 2θ = 2 sin θ cos θ, tan 2θ = 2tan θ/(1 − tan²θ).', 13),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'How do you write a sin x + b cos x as a single trigonometric function?', 'As R sin(x + α) with R = √(a² + b²) and tan α = b/a. The expression then ranges between −R and R.', 14),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'State the small angle approximations.', 'For small θ in RADIANS: sin θ ≈ θ, tan θ ≈ θ, cos θ ≈ 1 − θ²/2. Also (sin θ)/θ → 1 as θ → 0.', 15),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What goes wrong if you divide a trigonometric equation by cos x?', 'You lose every solution where cos x = 0. Factorise instead of dividing, and check those cases separately.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Convert 150° to radians.', '150 × π/180 = 5π/6.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Find the arc length of a sector with radius 6 cm and angle π/3.', 's = rθ = 6 × π/3 = 2π cm.', 18),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Find the area of a sector with radius 6 cm and angle π/3.', 'A = ½r²θ = ½ × 36 × π/3 = 6π cm².', 19),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What is the exact value of sin(π/6)?', '1/2.', 20),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What is the exact value of cos(π/4)?', '√2/2 (or 1/√2).', 21),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What is the exact value of tan(π/3)?', '√3.', 22),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What is the period of y = sin x and y = tan x?', 'sin x has period 2π (360°); tan x has period π (180°).', 23),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What is the identity linking tan, sin and cos?', 'tan θ = sin θ/cos θ.', 24),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What is 1 + tan²θ equal to?', 'sec²θ.', 25),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What is 1 + cot²θ equal to?', 'cosec²θ.', 26),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Solve sin x = 0.5 for 0 ≤ x < 2π.', 'x = π/6 or x = 5π/6.', 27),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'What are the principal value ranges of arcsin, arccos and arctan?', 'arcsin: −π/2 to π/2; arccos: 0 to π; arctan: −π/2 to π/2 (exclusive).', 28),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Write sin 3x cos x + cos 3x sin x as a single term.', 'sin(3x + x) = sin 4x.', 29),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Express 3 sin x + 4 cos x as R sin(x + α).', 'R = 5, tan α = 4/3, so α ≈ 0.927 rad (53.1°): 5 sin(x + 0.927).', 30),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Solve cos 2x = sin x for 0° ≤ x < 360°.', '1 − 2sin²x = sin x, so (2 sin x − 1)(sin x + 1) = 0. sin x = ½ or −1, giving x = 30°, 150°, 270°.', 31),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Solve sec²θ = 3 tan θ − 1 for 0° ≤ θ < 360°.', '1 + tan²θ = 3 tan θ − 1, so (tan θ − 1)(tan θ − 2) = 0. θ = 45°, 225°, 63.4°, 243.4°.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Prove that (1 − cos 2θ)/sin 2θ ≡ tan θ.', '(1 − cos 2θ)/sin 2θ = 2sin²θ/(2 sin θ cos θ) = sin θ/cos θ = tan θ.', 33),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Find the exact value of cos 15°.', 'cos(45° − 30°) = cos 45° cos 30° + sin 45° sin 30° = (√6 + √2)/4.', 34),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Use small angle approximations to estimate (1 − cos 2θ)/(θ sin θ) for small θ.', 'cos 2θ ≈ 1 − 2θ² and sin θ ≈ θ, so the expression ≈ 2θ²/θ² = 2.', 35),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Find the maximum of 3 sin x + 4 cos x and where it first occurs for x > 0.', '5 sin(x + 53.13°) has maximum 5 when x + 53.13° = 90°, i.e. x ≈ 36.9°.', 36),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Find the greatest and least values of 1/(10 + 3 sin x + 4 cos x).', '3 sin x + 4 cos x ranges from −5 to 5, so the denominator ranges from 5 to 15. Greatest 1/5, least 1/15.', 37),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Describe the graph of y = sec x.', 'Vertical asymptotes where cos x = 0 (x = 90°, 270°, …), a minimum of 1 at 0° and 360° and a maximum of −1 at 180°. No part lies between −1 and 1.', 38),
  ('Mathematics', 'AQA', 'alevel', '1.5', 'Trigonometry', 'Prove that cos⁴θ − sin⁴θ ≡ cos 2θ.', 'Difference of two squares: (cos²θ − sin²θ)(cos²θ + sin²θ) = cos 2θ × 1.', 39),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is the relationship between aˣ and log_a x?', 'They are inverse functions: x = a^y is equivalent to y = log_a x. Their graphs are reflections in y = x.', 1),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'State the three laws of logarithms.', 'log(xy) = log x + log y, log(x/y) = log x − log y, log(xᵏ) = k log x.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Is there a law for log(x + y)?', 'No. The addition law applies to a PRODUCT inside the logarithm, not a sum. log(x + y) ≠ log x + log y.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What are log_a a and log_a 1?', 'log_a a = 1 and log_a 1 = 0.', 4),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'How do you solve an equation such as 3ˣ = 20?', 'Take logarithms of both sides, then use the power law to bring x down: x = log 20 ÷ log 3 ≈ 2.727.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What must you check after solving a logarithmic equation?', 'That each solution keeps every logarithm''s argument positive. Reject any root that makes an argument zero or negative.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is special about e?', 'It is the base for which the gradient of y = eˣ equals eˣ itself. More generally the gradient of e^(kx) is k e^(kx).', 7),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Why does the exponential model suit so many situations?', 'Because the derivative of e^(kt) is proportional to the function itself — exactly the condition ''rate of change proportional to current size''.', 8),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is ln x, and what are ln e and e^(ln x)?', 'ln x is log to base e, the inverse of eˣ. ln e = 1, and e^(ln x) = x for x > 0.', 9),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'How do you reduce y = axⁿ to linear form?', 'Take logs: log y = log a + n log x. Plot log y against log x — gradient n, intercept log a.', 10),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'How do you reduce y = abˣ to linear form?', 'Take logs: log y = log a + x log b. Plot log y against PLAIN x — gradient log b, intercept log a.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'How do you tell a power law from an exponential law using graphs?', 'A power law gives a straight line on log–log axes, an exponential law gives one with log y against plain x. The difference is whether the horizontal axis carries a logarithm.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Write down the exponential growth and decay models.', 'N = N₀e^(kt) for growth and N = N₀e^(−kt) for decay, with k > 0 and N₀ the value at t = 0.', 13),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'How do you find the decay constant from a half-life T?', 'Set e^(−kT) = ½, so kT = ln 2 and k = (ln 2)/T.', 14),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Give two criticisms of an exponential population growth model.', 'It predicts unbounded growth, ignoring finite resources, and it assumes k stays constant, though it may drift with conditions. A logistic model adds a carrying capacity.', 15),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Solve 2ˣ = 8.', 'x = 3.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Solve eˣ = 5.', 'x = ln 5.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Simplify log 8 + log 5 − log 4.', 'log(8 × 5/4) = log 10.', 18),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Write 2 log x − log y as a single log.', 'log(x²/y).', 19),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is the gradient of y = eᵏˣ?', 'keᵏˣ.', 20),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is log_a aˣ equal to?', 'x.', 21),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is e^(ln 7)?', '7.', 22),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is ln(e³)?', '3.', 23),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Solve ln x = 2.', 'x = e².', 24),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is the change of base formula?', 'log_a b = log_c b / log_c a.', 25),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is the asymptote of y = eˣ?', 'y = 0 (the x-axis).', 26),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'What is the asymptote of y = ln x?', 'x = 0 (the y-axis).', 27),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'If y = axⁿ, what does a log–log graph give?', 'log y = log a + n log x: a straight line with gradient n and intercept log a.', 28),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'If y = abˣ, what does plotting log y against x give?', 'log y = log a + x log b: a straight line with gradient log b and intercept log a.', 29),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Solve 5^(2x) − 6 × 5^x + 5 = 0.', 'Let u = 5^x: u² − 6u + 5 = 0, so u = 1 or 5, giving x = 0 or x = 1.', 30),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Solve 2^(x + 1) = 3ˣ.', '(x + 1) ln 2 = x ln 3, so x(ln 3 − ln 2) = ln 2 and x = ln 2/ln 1.5 ≈ 1.71.', 31),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Solve log₂x + log₂(x − 2) = 3.', 'log₂(x(x − 2)) = 3, so x² − 2x − 8 = 0 and x = 4 or −2. Reject −2, since log₂(−2) is undefined. x = 4.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Solve e^(2x) − 5eˣ + 6 = 0.', '(eˣ − 2)(eˣ − 3) = 0, so x = ln 2 or x = ln 3.', 33),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'A car''s value is V = 20 000e^(−0.15t) after t years. When is it worth £10 000?', 'e^(−0.15t) = 0.5, so t = ln 2/0.15 ≈ 4.62 years.', 34),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'For N = 500e^(0.2t), what are the initial value and the initial rate of growth?', 'At t = 0, N = 500. dN/dt = 100e^(0.2t), which is 100 per unit time at t = 0.', 35),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Write ln y = 2 + 3 ln x without logarithms.', 'y = e^(2 + 3 ln x) = e² × x³.', 36),
  ('Mathematics', 'AQA', 'alevel', '1.6', 'Exponentials & Logarithms', 'Describe the graph of y = e^(−x) + 2.', 'Decreasing, crossing the y-axis at (0, 3), with horizontal asymptote y = 2 as x → ∞.', 37),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Write down the definition of the derivative as a limit.', 'f′(x) = limit as h → 0 of (f(x + h) − f(x))/h — the gradient of a chord becoming the gradient of the tangent.', 1),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Why must you cancel the h before letting h → 0?', 'Substituting h = 0 first gives 0/0, which is undefined. Cancelling is the whole point of the method.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'What are the derivatives of xⁿ, eˣ and ln x?', 'nxⁿ⁻¹, eˣ, 1/x.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'What are the derivatives of sin x, cos x and tan x?', 'cos x, −sin x, sec²x. These hold only when x is in RADIANS.', 4),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Why do the trigonometric derivatives require radians?', 'They follow from the limit (sin h)/h → 1, which is true only in radians. In degrees an extra constant factor appears.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'State the chain rule.', 'The derivative of f(g(x)) is f′(g(x)) × g′(x) — the outer derivative times the inner derivative.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'State the product rule.', 'The derivative of uv is u′v + uv′.', 7),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'State the quotient rule.', 'The derivative of u/v is (u′v − uv′)/v². Note the minus, and that the order matters — reversing it flips every sign.', 8),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'How do you differentiate implicitly?', 'Differentiate both sides with respect to x, applying the chain rule to every y term so each contributes a factor dy/dx, then collect and solve.', 9),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Why does a dy/dx appear when differentiating a y term?', 'Because y is itself a function of x, so the chain rule applies: differentiating f(y) with respect to x gives f′(y) × dy/dx.', 10),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'How do you differentiate an inverse function?', 'Use dy/dx = 1 ÷ (dx/dy). For y = ln x, write x = e^y, so dx/dy = e^y = x and dy/dx = 1/x.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'How do you find the gradient of a tangent and of a normal?', 'The tangent gradient is dy/dx at that point, the normal gradient is −1 divided by that value.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'How do you classify a stationary point using the second derivative?', 'Positive means minimum, negative means maximum, zero is inconclusive and requires checking the gradient either side.', 13),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Does d²y/dx² = 0 prove a point of inflection?', 'No. For y = x⁴ at the origin the second derivative is zero yet the point is a minimum. A genuine inflection needs the second derivative to CHANGE SIGN.', 14),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'How do connected rates of change work?', 'Link them by the chain rule, for example dV/dt = (dV/dr) × (dr/dt).', 15),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'What are the two marks most often lost in an optimisation question?', 'Not justifying that the stationary point is the required maximum or minimum, and not answering the quantity actually asked for.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = 3x⁴ − 2x + 7.', 'dy/dx = 12x³ − 2.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = √x.', 'y = x^(1/2), so dy/dx = ½x^(−1/2) = 1/(2√x).', 18),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = e^(3x).', 'dy/dx = 3e^(3x).', 19),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = ln(5x).', 'dy/dx = 1/x.', 20),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = sin(2x).', 'dy/dx = 2 cos(2x).', 21),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = (2x + 1)⁵.', 'dy/dx = 5(2x + 1)⁴ × 2 = 10(2x + 1)⁴.', 22),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = x² eˣ.', 'Product rule: dy/dx = 2x eˣ + x² eˣ = x eˣ(2 + x).', 23),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = (sin x)/x.', 'Quotient rule: dy/dx = (x cos x − sin x)/x².', 24),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'What is the derivative of aˣ?', 'aˣ ln a.', 25),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'What does it mean if dy/dx > 0?', 'The function is increasing.', 26),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'What does a positive second derivative indicate?', 'The curve is concave upwards (convex), and a stationary point there is a minimum.', 27),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'What is a point of inflection?', 'A point where the curve changes concavity (d²y/dx² changes sign).', 28),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Find the gradient of x² + y² = 25 at (3, 4).', '2x + 2y dy/dx = 0, so dy/dx = −x/y = −3/4.', 29),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'What is the derivative of sec x?', 'sec x tan x.', 30),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate x² from first principles.', '((x + h)² − x²)/h = (2xh + h²)/h = 2x + h, which tends to 2x as h → 0.', 31),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Outline the first-principles derivative of sin x, which AQA requires.', '[sin(x + h) − sin x]/h = sin x × (cos h − 1)/h + cos x × (sin h)/h. As h → 0, (cos h − 1)/h → 0 and (sin h)/h → 1, giving cos x.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'What are the derivatives of cosec x and cot x?', '−cosec x cot x and −cosec²x.', 33),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = ln(sin x).', 'dy/dx = cos x/sin x = cot x.', 34),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Find and classify the stationary points of y = x³ − 3x + 2.', 'dy/dx = 3x² − 3 = 0 at x = ±1. d²y/dx² = 6x: (1, 0) is a minimum and (−1, 4) is a maximum.', 35),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate xy and e^y implicitly with respect to x.', 'xy gives y + x dy/dx (product rule). e^y gives e^y dy/dx (chain rule).', 36),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'The radius of a sphere grows at 0.1 cm s⁻¹. How fast is the volume increasing when r = 5 cm?', 'dV/dt = (dV/dr)(dr/dt) = 4πr² × 0.1 = 4π × 25 × 0.1 = 10π cm³ s⁻¹.', 37),
  ('Mathematics', 'AQA', 'alevel', '1.7', 'Differentiation', 'Differentiate y = tan 3x.', 'dy/dx = 3 sec²3x.', 38),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'What is the integral of xⁿ, and when does it fail?', 'x^(n+1)/(n + 1) + c, failing for n = −1 where the denominator would be zero. Then the integral of 1/x is ln|x| + c.', 1),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Why is the modulus written in ln|x|?', 'So the result is valid for negative x too, since the logarithm of a negative number is undefined.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Why does an indefinite integral need + c but a definite one does not?', 'Differentiating a constant gives zero, so it cannot be recovered. In a definite integral the constant appears in both F(b) and F(a) and cancels.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'State the Fundamental Theorem of Calculus.', 'The definite integral from a to b of f equals F(b) − F(a), where F′ = f. It links area with the antiderivative and shows the two processes are inverse.', 4),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'What happens to a region below the x-axis in a definite integral?', 'It contributes a negative amount. If the curve crosses the axis within the limits, split there and add the magnitudes, or the parts will cancel.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'How do you find the area between two curves?', 'Integrate (upper − lower) between the intersections, so the integrand is non-negative and the area comes out positive.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'When is integration by substitution the right method?', 'When the integrand contains an inner function together with its derivative — for example x e^(x²), where u = x² gives du = 2x dx.', 7),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'What must you also change when substituting in a DEFINITE integral?', 'The limits, converting them to values of u — or substitute back to x before applying the original limits.', 8),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'State the standard result for f′(x)/f(x).', 'Its integral is ln|f(x)| + c. For example the integral of 2x/(x² + 1) is ln(x² + 1) + c.', 9),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'State the integration by parts formula.', 'The integral of u(dv/dx) equals uv minus the integral of v(du/dx) — the reverse of the product rule.', 10),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'How do you choose u when integrating by parts?', 'Choose u to be the factor that becomes SIMPLER when differentiated, and dv/dx to be one you can integrate.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'How do you integrate ln x?', 'Write it as 1 × ln x, take u = ln x and dv/dx = 1. This gives x ln x − x + c.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'How do you integrate eˣ sin x?', 'Apply parts twice, the original integral reappears, so treat it as an unknown and solve the resulting equation algebraically.', 13),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Why are partial fractions useful in integration?', 'A fraction with a factorised denominator has no standard integral, but splitting it gives terms A/(x + a), each integrating to a logarithm.', 14),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'How do you integrate cos²x?', 'Use the double angle identity cos²x = ½(1 + cos 2x), giving x/2 + (sin 2x)/4 + c.', 15),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'What are the integrals of sin x, cos x and sec²x?', '−cos x + c, sin x + c, tan x + c. The minus on the sine integral is the one most often dropped.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate 6x² + 4x − 3.', '2x³ + 2x² − 3x + c.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate 1/x².', '−1/x + c.', 18),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate e^(2x).', '½e^(2x) + c.', 19),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate 1/x.', 'ln|x| + c.', 20),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate cos(3x).', '⅓ sin(3x) + c.', 21),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate (2x + 1)³.', '(2x + 1)⁴/8 + c.', 22),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'What is the difference between a general and a particular solution?', 'A general solution contains an arbitrary constant and represents a family of curves, a particular solution uses an initial condition to fix that constant.', 23),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'How do you separate the variables?', 'If dy/dx = f(x)g(y), gather all the y terms with dy and all the x terms with dx, then integrate both sides.', 24),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Translate ''the rate of growth is proportional to the size'' into an equation.', 'dP/dt = kP. For decay it is dN/dt = −kN with k positive.', 25),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Translate ''the rate is proportional to the square of the population''.', 'dP/dt = kP².', 26),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Write down Newton''s law of cooling.', 'dθ/dt = −k(θ − θ₀), where θ₀ is the temperature of the surroundings — the rate is proportional to the excess temperature.', 27),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'What is the solution of dP/dt = kP with P = P₀ at t = 0?', 'P = P₀e^(kt).', 28),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Why is it useful to write the constant as ln A?', 'It turns an additive constant into a multiplicative one, so ln y = ln x + c becomes y = Ax instead of y = e^c × x.', 29),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Solve dy/dx = xy with y = 1 at x = 0.', 'Separate to (1/y)dy = x dx, integrate to ln y = x²/2 + c, apply the condition to get c = 0, so y = e^(x²/2).', 30),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate x eˣ.', 'By parts with u = x: x eˣ − eˣ + c.', 31),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate x cos x.', 'By parts with u = x: x sin x + cos x + c.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Evaluate the integral of 2x(x² + 1)³ from 0 to 1.', 'With u = x² + 1 the limits become 1 and 2: [u⁴/4] from 1 to 2 = (16 − 1)/4 = 15/4.', 33),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate 1/(x(x + 1)).', 'Partial fractions 1/x − 1/(x + 1) give ln|x| − ln|x + 1| + c = ln|x/(x + 1)| + c.', 34),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate tan x.', '−ln|cos x| + c, which is ln|sec x| + c.', 35),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate sin²x.', 'sin²x = ½(1 − cos 2x), so x/2 − (sin 2x)/4 + c.', 36),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Find the area enclosed by y = x² and y = 2x.', 'They meet at x = 0 and x = 2. The integral of (2x − x²) from 0 to 2 is 4 − 8/3 = 4/3.', 37),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'How is a definite integral the limit of a sum?', 'The area is approximated by Σ f(x)δx over thin strips. As δx → 0 the sum tends to the integral of f(x) from a to b.', 38),
  ('Mathematics', 'AQA', 'alevel', '1.8', 'Integration', 'Integrate sec²2x.', '½ tan 2x + c.', 39),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'State the change of sign condition for locating a root.', 'If f is CONTINUOUS on [a, b] and f(a), f(b) have opposite signs, then f(x) = 0 has at least one root in (a, b).', 1),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Which part of the change of sign argument is most often omitted?', 'The statement that f is continuous on the interval. Without it the argument is invalid.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Name two situations in which a change of sign method fails.', 'A repeated root, where the curve touches without crossing, e.g. (x − 2)², and a vertical asymptote, e.g. 1/(x − 2), where the sign changes but there is no root.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'How do you show a root is 1.86 correct to 2 decimal places?', 'Show f changes sign between the rounding bounds 1.855 and 1.865, so every value in that interval rounds to 1.86.', 4),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What is fixed point iteration?', 'Rearrange f(x) = 0 into x = g(x), choose a starting value, then apply x₍ₙ₊₁₎ = g(xₙ) repeatedly.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'When does a fixed point iteration converge?', 'When |g′(x)| < 1 near the root. If |g′(x)| > 1 it diverges, so different rearrangements of the same equation can behave differently.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What is the difference between a staircase and a cobweb diagram?', 'Both are drawn between y = g(x) and y = x. A staircase occurs when g′(x) > 0, a cobweb, spiralling and alternating sides, when g′(x) < 0.', 7),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'State the Newton-Raphson formula and its geometric meaning.', 'x₍ₙ₊₁₎ = xₙ − f(xₙ)/f′(xₙ). Follow the tangent at the current point down to where it meets the x-axis.', 8),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Why does Newton-Raphson converge faster than a simple iteration?', 'Near a simple root the error is roughly SQUARED at each step, so the number of correct digits approximately doubles.', 9),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'When does Newton-Raphson fail?', 'When f′(xₙ) = 0, since the tangent is horizontal and never meets the axis, and near a stationary point, where a nearly horizontal tangent throws the next estimate far away.', 10),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'State the trapezium rule.', 'With h = (b − a)/n, the integral is approximately (h/2)[y₀ + yₙ + 2(y₁ + … + y₍ₙ₋₁₎)] — first and last counted once, interior ordinates doubled.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'How many ordinates are needed for n strips?', 'n + 1, since adjacent strips share an ordinate.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'When does the trapezium rule give an over- or under-estimate?', 'Concave upwards: chords lie above the curve, so it is an OVERestimate. Concave downwards: chords lie below, so it is an UNDERestimate.', 13),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'How should you justify the direction of a trapezium error?', 'Refer to the concavity: ''the curve is concave upwards on this interval, so each chord lies above it and the estimate is too large''.', 14),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What happens to the trapezium rule error if you halve the strip width?', 'It reduces by a factor of roughly 4, since the error is approximately proportional to the square of the width.', 15),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'How can rectangles give bounds on an integral?', 'For a monotonic function, left-hand and right-hand rectangle sums lie on either side of the true value, bracketing it.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What does the change of sign method rely on?', 'If f is continuous on [a, b] and f(a) and f(b) have opposite signs, there is a root between a and b.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Why can a change of sign occur without a root?', 'At a vertical asymptote (discontinuity), e.g. f(x) = 1/x between −1 and 1.', 18),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Why might there be a root with no change of sign?', 'A repeated root where the curve touches the x-axis, or two roots close together.', 19),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What is decimal search?', 'Checking values at intervals of 0.1, then 0.01, etc., to locate a root by change of sign.', 20),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What is interval bisection?', 'Repeatedly halving the interval containing the root and keeping the half with a sign change.', 21),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'How do you rearrange f(x) = 0 into x = g(x)?', 'Make x the subject of part of the equation, e.g. x³ − x − 1 = 0 → x = ∛(x + 1).', 22),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What is the convergence condition for xₙ₊₁ = g(xₙ)?', '|g′(x)| < 1 near the root.', 23),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What is a staircase diagram?', 'A diagram showing iteration converging monotonically, when 0 < g′(x) < 1.', 24),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What is a cobweb diagram?', 'A diagram showing iteration oscillating around the root, when −1 < g′(x) < 0.', 25),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Apply one step of Newton–Raphson to f(x) = x² − 2 from x₀ = 1.', 'x₁ = 1 − (1 − 2)/2 = 1.5.', 26),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'When does the trapezium rule give an overestimate?', 'When the curve is concave up (convex) over the interval.', 27),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'When does the trapezium rule give an underestimate?', 'When the curve is concave down over the interval.', 28),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'How do you improve the accuracy of the trapezium rule?', 'Increase the number of strips (decrease the strip width).', 29),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'What is the width h in the trapezium rule?', 'h = (b − a)/n, where n is the number of strips.', 30),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Use the trapezium rule with 2 strips to estimate the integral of x² from 0 to 2.', 'h = 1: ½ × 1 × (0 + 4 + 2 × 1) = 3. The exact value is 8/3, so this overestimates — the curve is convex.', 31),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Apply one step of Newton-Raphson to x³ − 2x − 5 = 0 from x₀ = 2.', 'f(2) = −1 and f′(2) = 3 × 4 − 2 = 10, so x₁ = 2 − (−1/10) = 2.1.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Show that x³ + x − 3 = 0 has a root between 1 and 2.', 'f(1) = −1 < 0 and f(2) = 7 > 0. f is continuous, so there is a sign change and a root lies in (1, 2).', 33),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Find x₁ and x₂ for xₙ₊₁ = √(xₙ + 2) with x₀ = 1. What is the limit?', 'x₁ = √3 ≈ 1.732, x₂ ≈ 1.932. The limit L satisfies L = √(L + 2), so L² − L − 2 = 0 and L = 2.', 34),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Why is the limit of xₙ₊₁ = g(xₙ) a root of f(x) = 0?', 'At the limit L = g(L), and x = g(x) was obtained by rearranging f(x) = 0, so f(L) = 0.', 35),
  ('Mathematics', 'AQA', 'alevel', '1.9', 'Numerical Methods', 'Why might Newton-Raphson find a different root from the one you want?', 'If the starting value is far from the root, or near a turning point, the tangent can send the next estimate towards another root.', 36),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What is the difference between a scalar and a vector?', 'A scalar has magnitude only (mass, time, speed), a vector has magnitude and direction (displacement, velocity, force).', 1),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'How are vectors written in print and by hand?', 'Bold in print, underlined by hand. The magnitude is written |a| or a in italic.', 2),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'How do you find the magnitude of a vector in 2D and 3D?', '√(a₁² + a₂²) in two dimensions, √(a₁² + a₂² + a₃²) in three.', 3),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'How do you find a unit vector in the direction of a?', 'Divide a by its magnitude: â = a/|a|. For 6i − 8j, the magnitude is 10 so the unit vector is 0.6i − 0.8j.', 4),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'When are two non-zero vectors parallel?', 'When one is a scalar multiple of the other. A negative scalar reverses the direction but they remain parallel.', 5),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Write down the vector AB in terms of position vectors.', 'AB = b − a — destination minus start. Reversing it gives the same magnitude in the opposite direction.', 6),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'How do you find the distance between two points from their position vectors?', 'It is |b − a|, the magnitude of the vector joining them.', 7),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What is the position vector of the midpoint of AB?', '(a + b)/2. More generally the point dividing AB in the ratio m : n is (na + mb)/(m + n).', 8),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'How do you convert between component and magnitude-direction form?', 'a₁ = r cos θ and a₂ = r sin θ, conversely r = √(a₁² + a₂²) and tan θ = a₂/a₁.', 9),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Why is arctan alone not enough to give a direction?', 'It returns angles only in the first and fourth quadrants. Use the signs of the components to identify the quadrant and adjust — (−3, −4) gives 233.1°, not 53.1°.', 10),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'How do you prove three points collinear using vectors?', 'Show one joining vector is a scalar multiple of another, AND state that they share a common point. Parallel alone is not enough.', 11),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What does the sum of force vectors represent?', 'The resultant force. The specification explicitly includes using vectors for problems involving forces.', 12),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What is the condition for a set of forces to be in equilibrium?', 'Their vector sum is the zero vector, so drawn head to tail they form a closed figure.', 13),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Is |a + b| equal to |a| + |b|?', 'Not in general. It lies between ||a| − |b|| and |a| + |b|, reaching the upper value only when the vectors point the same way.', 14),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'How does 3D vector work extend the 2D case?', 'A third component along k is added. Magnitudes involve the sum of three squares, and all the 2D techniques carry over.', 15),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What is the zero vector?', 'A vector with zero magnitude and no specific direction.', 16),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Find the magnitude of 3i − 4j.', '√(9 + 16) = 5.', 17),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Find the unit vector in the direction of 3i − 4j.', '(3i − 4j)/5 = 0.6i − 0.8j.', 18),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'If a = 2i + j and b = i − 3j, find 2a − b.', '4i + 2j − i + 3j = 3i + 5j.', 19),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What is a position vector?', 'A vector giving the position of a point relative to the origin.', 20),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Find the direction of 3i + 3j.', '45° above the positive x-axis.', 21),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What is the magnitude of 2i − j + 2k?', '√(4 + 1 + 4) = 3.', 22),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'How do you find a vector of magnitude 10 in the direction of 3i + 4j?', 'Unit vector (3i + 4j)/5, times 10: 6i + 8j.', 23),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'If AB = b − a, what is BA?', 'a − b.', 24),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What is the resultant of forces (3i + 2j) N and (−i + 4j) N?', '2i + 6j N.', 25),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Express 10 N at 30° above the x-axis in component form.', '10 cos 30° i + 10 sin 30° j = 5√3 i + 5j N.', 26),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'How do you show two vectors are parallel?', 'Show one is a scalar multiple of the other.', 27),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What is a column vector?', 'A vector written vertically with components, e.g. (3, 4) written as a column.', 28),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'What does it mean for vectors to be equal?', 'They have the same magnitude and direction (equal components).', 29),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Find the angle between the vector 3i + 4j and the positive x-axis.', 'tan θ = 4/3, so θ ≈ 53.1°.', 30),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Is the scalar (dot) product part of AQA A-level Maths (7357)?', 'No. The scalar product is AQA Further Maths content. In 7357 vectors cover magnitude, direction, position vectors, geometric problems and forces in 2D and 3D.', 31),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Find the distance between A(1, 2, 3) and B(4, 6, 3).', 'AB = 3i + 4j + 0k, so |AB| = √(9 + 16) = 5.', 32),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'P divides AB in the ratio 1 : 2. Express OP in terms of a and b.', 'OP = a + ⅓(b − a) = ⅔a + ⅓b.', 33),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'Find λ so that λi + 2j is parallel to 3i − 6j.', 'λ/3 = 2/(−6), so λ = −1.', 34),
  ('Mathematics', 'AQA', 'alevel', '1.10', 'Vectors', 'A particle is in equilibrium under 2i − 3j, pi + qj and −5i + j. Find p and q.', 'The resultant is zero: 2 + p − 5 = 0 and −3 + q + 1 = 0, so p = 3 and q = 2.', 35),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is the difference between a population and a sample?', 'A population is the entire group being studied, a sample is a subset used to draw conclusions about it.', 1),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is the difference between a parameter and a statistic?', 'A parameter describes the POPULATION, a statistic is calculated from a SAMPLE and used to estimate it.', 2),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Define simple random sampling.', 'Every possible sample of the required size has the same probability of being selected. It requires a complete sampling frame.', 3),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is a sampling frame?', 'A list of all members of the population, from which the sample is drawn. An incomplete frame means some members can never be selected.', 4),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Describe systematic sampling and its main risk.', 'Select every kth member of an ordered list. It fails if the list has a repeating pattern matching the sampling interval.', 5),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Describe stratified sampling.', 'Divide the population into strata and sample each in proportion to its size, selecting AT RANDOM within each stratum.', 6),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Name the four types of data.', 'Categorical (labels), discrete (separate numerical values), continuous (any value in a range) and ranked (ordered positions).', 7),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'In a histogram, what represents frequency?', 'The AREA of each bar. The vertical axis is frequency density, which is frequency divided by class width.', 8),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'How does a frequency chart differ from a histogram?', 'A frequency chart has equal-width bars with FREQUENCY on the vertical axis, a histogram may have unequal widths and uses frequency density.', 9),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What does a box-and-whisker diagram show?', 'The median, the lower and upper quartiles, and the extreme values. The box spans the interquartile range.', 10),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'When is the median preferred to the mean?', 'For skewed data or when outliers are present, since the median depends only on position in the order and resists extremes.', 11),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'When is a weighted mean appropriate?', 'When combining groups of different sizes, weighting each group mean by the size of that group.', 12),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'How is probability calculated for equally likely outcomes?', 'Favourable outcomes divided by total outcomes. Every probability lies between 0 and 1 inclusive.', 13),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is a complementary event?', 'A′ is the event that A does not occur, and P(A′) = 1 − P(A). It is the fastest route for ''at least one'' questions.', 14),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is the expected frequency of an event in n trials?', 'nP(A). In 200 trials with probability 0.15, the expected frequency is 30.', 15),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What do A ∩ B and A ∪ B mean?', 'A ∩ B means both occur. A ∪ B means A or B or both occur.', 16),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Define mutually exclusive events and give the addition rule.', 'They cannot both occur, so P(A ∩ B) = 0 and P(A ∪ B) = P(A) + P(B).', 17),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Define independent events and give the multiplication rule.', 'The occurrence of one does not affect the probability of the other, so P(A ∩ B) = P(A)P(B).', 18),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is a discrete random variable?', 'A variable taking separate values each with a given probability. Capital X denotes the variable, lower-case x or r a particular value.', 19),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What condition must a discrete probability distribution satisfy?', 'All probabilities non-negative and summing to 1.', 20),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is a discrete uniform distribution?', 'One in which all outcomes are equally likely, such as the score on a fair die.', 21),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'State the four conditions for a binomial model.', 'A fixed number of trials, exactly two outcomes per trial, the same probability of success each time, and independent trials.', 22),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What does X ~ B(n, p) mean?', 'X has the binomial distribution with n trials and probability p of success. The symbol ~ is read ''has the distribution''.', 23),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Write down the binomial probability formula.', 'P(X = r) = ⁿCᵣ pʳ q^(n−r), where q = 1 − p.', 24),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What are the null and alternative hypotheses?', 'H₀ is the default assumption being tested, always an equality. H₁ is what is concluded if H₀ is rejected.', 25),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Must hypotheses refer to the sample or the population?', 'The POPULATION parameter — p or μ. Writing H₀: x̄ = 50 is wrong, it must be H₀: μ = 50.', 26),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is the significance level?', 'The probability of incorrectly rejecting a TRUE null hypothesis. It sets the size of the critical region.', 27),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Define critical region, acceptance region and critical value.', 'The critical (rejection) region contains test statistic values leading to rejection, the acceptance region those that do not, the critical value is the boundary.', 28),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is a p-value and how is it used?', 'The probability of a result at least as extreme as the one observed, assuming H₀. Reject H₀ if it is below the significance level.', 29),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'When is a test one-tailed and when two-tailed?', 'One-tailed when H₁ specifies a DIRECTION (''biased towards heads''), two-tailed when it does not (''biased'', ''has changed'').', 30),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is opportunity (convenience) sampling?', 'Taking the sample from people or items available at the time. It is quick and cheap but unlikely to be representative.', 31),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is quota sampling?', 'The interviewer fills quotas so each group appears in proportion to the population. It is not random, so selection can be biased.', 32),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is cluster sampling?', 'The population is split into naturally occurring groups (clusters), clusters are chosen at random and members of those clusters are surveyed.', 33),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Why is a census rarely used?', 'It is time-consuming and expensive, the data are hard to process, and testing that destroys items would destroy the whole population.', 34),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Why must you be familiar with the AQA large data set?', 'Paper 3 questions assume familiarity with its context (DEFRA Family Food data on household food and drink purchases) — knowing it helps you interpret questions and spot implausible values.', 35),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Give a formula for the variance of n values.', 'Variance = Σ(x − x̄)²/n = Σx²/n − x̄², the mean of the squares minus the square of the mean. Standard deviation is its square root.', 36),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Find the mean and standard deviation of 2, 4, 4, 4, 5, 5, 7, 9.', 'Mean 40/8 = 5. Σx²/n = 232/8 = 29, so variance = 29 − 25 = 4 and standard deviation = 2.', 37),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'n = 10, Σx = 50 and Σx² = 290. Find the mean and standard deviation.', 'Mean 5. Variance 290/10 − 5² = 4, so standard deviation 2.', 38),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Give a common rule for identifying outliers.', 'Values below Q1 − 1.5 × IQR or above Q3 + 1.5 × IQR. Another is more than 2 (or 3) standard deviations from the mean. Always use the rule the question gives.', 39),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Should outliers always be removed?', 'No. Remove them only if they are errors. Genuine extreme values belong in the data and should be discussed in context.', 40),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'How do you estimate the median from grouped data?', 'Find the class containing the (n/2)th value, then use linear interpolation within that class.', 41),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'How can you recognise positive skew?', 'A longer tail to the right. Typically mode < median < mean, and on a box plot Q3 − Q2 > Q2 − Q1.', 42),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is the difference between explanatory and response variables?', 'The explanatory (independent) variable is set or changed and goes on the x-axis. The response (dependent) variable is measured and goes on the y-axis.', 43),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What does the product moment correlation coefficient r measure?', 'The strength of LINEAR correlation, −1 ≤ r ≤ 1. Near 1: strong positive, near −1: strong negative, near 0: no linear correlation.', 44),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Does strong correlation imply causation?', 'No. A third (confounding) variable or coincidence may explain it.', 45),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is the difference between interpolation and extrapolation?', 'Interpolation predicts within the range of the data and is fairly reliable. Extrapolation predicts outside it and is unreliable.', 46),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Interpret b in the regression line y = a + bx.', 'The predicted change in y for each one-unit increase in x, stated in context.', 47),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Can a regression line of y on x be used to predict x from y?', 'No, it should only predict y from a given x.', 48),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'State the formula for conditional probability.', 'P(A | B) = P(A ∩ B)/P(B).', 49),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'How can conditional probability show independence?', 'A and B are independent if P(A | B) = P(A), equivalently P(A ∩ B) = P(A)P(B).', 50),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'State the general addition rule.', 'P(A ∪ B) = P(A) + P(B) − P(A ∩ B).', 51),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'P(A) = 0.4, P(B) = 0.5 and P(A ∪ B) = 0.7. Are A and B independent?', 'P(A ∩ B) = 0.4 + 0.5 − 0.7 = 0.2 = 0.4 × 0.5, so yes.', 52),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'How do you find P(first event | second event) from a tree diagram?', 'Divide P(both) by P(second), where P(second) is the sum of every branch path that gives the second event.', 53),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'State the mean and variance of X ~ B(n, p).', 'Mean np, variance np(1 − p).', 54),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'X ~ B(10, 0.3). Find P(X = 2).', '¹⁰C₂ × 0.3² × 0.7⁸ = 45 × 0.09 × 0.0576… ≈ 0.233.', 55),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'How do you find P(X ≥ 3) and P(3 ≤ X < 7) with cumulative binomial probabilities?', 'P(X ≥ 3) = 1 − P(X ≤ 2). P(3 ≤ X < 7) = P(X ≤ 6) − P(X ≤ 2).', 56),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'State the key properties of the normal distribution.', 'Bell-shaped and symmetrical about μ, so mean = median = mode. Points of inflection at μ ± σ. About 68%, 95% and 99.7% of values lie within 1, 2 and 3 standard deviations.', 57),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'X ~ N(50, 16). What is the standard deviation?', '4. The second parameter is the variance σ², not σ.', 58),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'X ~ N(50, 4²). Find P(X > 58).', 'Z = (58 − 50)/4 = 2, so P = 1 − Φ(2) ≈ 0.0228.', 59),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'X ~ N(μ, 5²) and P(X < 30) = 0.9. Find μ.', '(30 − μ)/5 = 1.2816, so μ ≈ 23.6.', 60),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'When can a normal distribution approximate B(n, p)?', 'When n is large and p is close to 0.5 (np and n(1 − p) both greater than about 5). Use μ = np, σ² = np(1 − p) and a continuity correction.', 61),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is the distribution of the sample mean of n observations from N(μ, σ²)?', 'X̄ ~ N(μ, σ²/n).', 62),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'In a two-tailed test at the 5% level, how is the significance level split?', '2.5% in each tail.', 63),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'Find the 5% lower-tail critical region for X ~ B(20, 0.5).', 'P(X ≤ 5) ≈ 0.0207 and P(X ≤ 6) ≈ 0.0577 > 0.05, so the critical region is X ≤ 5.', 64),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is the actual significance level of a binomial test?', 'The probability of landing in the critical region when H₀ is true — e.g. P(X ≤ 5) ≈ 0.0207 for the B(20, 0.5) test.', 65),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'State the hypotheses for a test of correlation.', 'H₀: ρ = 0, H₁: ρ > 0, ρ < 0 or ρ ≠ 0, where ρ is the population correlation coefficient. Compare r with the critical value for the sample size.', 66),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'r = 0.62 from 10 pairs. The one-tailed 5% critical value is 0.5494. Conclusion?', '0.62 > 0.5494, so reject H₀. There is evidence at the 5% level of positive correlation in the population.', 67),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'What is the test statistic for a normal mean with known variance?', 'Z = (x̄ − μ₀)/(σ/√n), compared with the critical z-value.', 68),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'μ₀ = 50, σ = 4, n = 16 and x̄ = 52. Test H₁: μ > 50 at the 5% level.', 'Z = 2/(4/4) = 2 > 1.6449, so reject H₀. There is evidence that the mean has increased.', 69),
  ('Mathematics', 'AQA', 'alevel', '2.1', 'Statistics', 'How should a hypothesis test conclusion be worded?', 'In context and without certainty: ''there is sufficient evidence at the 5% level to suggest that…'', never ''this proves…''.', 70),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What is the difference between distance travelled and displacement?', 'Distance travelled is the total path length, a scalar, displacement is the net change in position, a vector.', 1),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What is the difference between speed and velocity?', 'Speed is the magnitude of velocity, so it is a scalar and never negative, velocity carries direction.', 2),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Give the formulae for average speed and average velocity.', 'Average speed = distance travelled ÷ time, average velocity = overall displacement ÷ time. A there-and-back journey has zero average velocity.', 3),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What do the gradient and area of a velocity-time graph give?', 'Gradient gives acceleration, area gives displacement.', 4),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What does the gradient of a displacement-time graph give?', 'Velocity.', 5),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'How are velocity and acceleration obtained from a position vector?', 'By differentiating with respect to t, component by component. Integrating reverses the process.', 6),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Why can vector calculus be done component by component?', 'The i and j directions are fixed and independent of time, so each component is an independent function of t.', 7),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What is the speed of a particle with velocity v?', '|v|, the magnitude — a scalar. Quoting a speed as a vector loses the mark.', 8),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'If r = 3t i + t² j, what are v and a?', 'v = 3i + 2t j and a = 2j. At t = 2 the speed is |3i + 4j| = 5.', 9),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'State the four standard projectile modelling assumptions.', 'No air resistance, the projectile is a particle, gravity always acts in the same direction, gravity is constant in magnitude.', 10),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What is the central idea that makes projectile problems work?', 'Horizontal and vertical motion are INDEPENDENT. Horizontally there is no acceleration, vertically the acceleration is g downwards. Time links them.', 11),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Give the initial velocity components for launch at speed u and angle θ.', 'Horizontal u cos θ, vertical u sin θ.', 12),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Give the displacement components at time t.', 'Horizontal u cos θ × t, vertical u sin θ × t − ½gt².', 13),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Write down the time of flight, maximum height and range on level ground.', 'T = 2u sin θ/g. H = u²sin²θ/(2g). R = u² sin 2θ/g.', 14),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Name four common forces and their directions.', 'Weight acts vertically downwards, normal reaction perpendicular to the surface, tension along a string pulling inwards, friction along the surface opposing motion.', 15),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What is the difference between tension and thrust?', 'Tension pulls the ends together, thrust pushes them apart. A string can only pull, a rod can do either.', 16),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Is the normal reaction always equal to the weight?', 'No. It depends on the other forces: pressing down increases it, pulling upwards at an angle reduces it, and on a slope it is mg cos θ.', 17),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Give the components of weight on a plane inclined at θ.', 'mg sin θ along the plane and mg cos θ perpendicular to it. Check with θ = 0: sin 0 = 0, so the along-plane component vanishes as it should.', 18),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Why resolve parallel and perpendicular to an inclined plane?', 'It puts the normal reaction on one axis and the friction on the other, so each equation contains fewer unknowns.', 19),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'State Newton''s first law.', 'An object continues at rest or in uniform motion in a straight line unless acted on by a resultant force.', 20),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'State Newton''s second law.', 'A resultant force F on an object of fixed mass m gives acceleration a with F = ma.', 21),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'State Newton''s third law.', 'When one object exerts a force on another, there is a reaction equal in magnitude and opposite in direction.', 22),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What must the F in F = ma be?', 'The RESULTANT of all forces acting. Using a single force and ignoring friction or weight is the standard structural error.', 23),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'How do you write down an equation of motion?', 'Draw a force diagram, choose a positive direction (usually that of the acceleration), resolve in that direction and set the total equal to ma.', 24),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'How is equilibrium a special case of the second law?', 'Setting a = 0 gives a resultant force of zero — which also recovers the first law.', 25),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Why does the point of application matter for a rigid body but not a particle?', 'A particle has no size, so forces only translate it. A rigid body has extent, so forces can also produce a turning effect.', 26),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Define the moment of a force and give its units.', 'Moment = force × perpendicular distance from the point. Units are newton metres, N m.', 27),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What is the moment of a force acting through the pivot?', 'Zero, since the perpendicular distance is zero. This is why choosing the pivot cleverly removes unknowns.', 28),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'State the two conditions for a rigid body to be in equilibrium.', 'The resultant force is zero, AND the sum of the moments about any one point is zero.', 29),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Why is the force condition alone insufficient?', 'Two equal and opposite forces applied at different points give no net force but do produce a turning effect.', 30),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What SI units are used in A-level mechanics?', 'Base units kg, m and s. Derived units include m s⁻¹, m s⁻², newtons (1 N = 1 kg m s⁻²) and N m for moments.', 31),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What do the modelling words light, inextensible, smooth, uniform and rigid mean?', 'Light: negligible mass. Inextensible: does not stretch, so connected objects share an acceleration. Smooth: no friction. Uniform: mass evenly spread, so weight acts at the centre. Rigid: does not bend.', 32),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'What value of g does AQA use?', '9.8 m s⁻² unless the question says otherwise.', 33),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'List the five constant-acceleration (suvat) equations.', 'v = u + at, s = ut + ½at², s = vt − ½at², v² = u² + 2as, s = ½(u + v)t.', 34),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'When can the suvat equations be used?', 'Only when acceleration is constant. If it varies with time, use calculus.', 35),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A car accelerates uniformly from 5 m s⁻¹ to 25 m s⁻¹ in 8 s. How far does it travel?', 's = ½(u + v)t = ½(5 + 25) × 8 = 120 m.', 36),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A ball is thrown vertically up at 14.7 m s⁻¹. Find its greatest height and the time to reach it.', 'At the top v = 0: s = 14.7²/(2 × 9.8) ≈ 11.0 m, and t = 14.7/9.8 = 1.5 s.', 37),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'How do you find velocity and displacement when acceleration varies with time?', 'v = ∫a dt and s = ∫v dt, using initial conditions for the constants. In reverse, v = ds/dt and a = dv/dt.', 38),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'v = 3t² − 12t for t ≥ 0. When is the particle at rest?', '3t(t − 4) = 0, so at t = 0 and t = 4 s.', 39),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'v = 3t² − 12t. Find the displacement and distance from t = 0 to t = 4.', 'Integral = [t³ − 6t²] from 0 to 4 = −32 m. v ≤ 0 throughout, so the distance is 32 m.', 40),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'How do you find distance travelled when velocity changes sign?', 'Split the integral where v = 0 and add the magnitudes of each part.', 41),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'v = 6t − t². Find the maximum velocity.', 'dv/dt = 6 − 2t = 0 at t = 3, giving v = 18 − 9 = 9 m s⁻¹.', 42),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'State the model for friction.', 'F ≤ μR. Friction is limiting, F = μR, when the object is moving or on the point of moving.', 43),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A 5 kg block on a rough horizontal surface (μ = 0.4) is pulled by a horizontal 30 N force. Find its acceleration.', 'R = 5g = 49 N, so F = 19.6 N. a = (30 − 19.6)/5 = 2.08 m s⁻².', 44),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A particle on a rough plane inclined at θ is on the point of slipping. Show μ = tan θ.', 'Along the plane F = mg sin θ. Perpendicular R = mg cos θ. Limiting friction F = μR gives μ = tan θ.', 45),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A force P pulls a block on a horizontal surface at angle α above the horizontal. What is R?', 'R = mg − P sin α, since the upward component of P reduces the normal reaction.', 46),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Masses of 3 kg and 2 kg hang on a light inextensible string over a smooth pulley. Find a and T.', '3g − T = 3a and T − 2g = 2a, so a = g/5 = 1.96 m s⁻² and T = 23.52 N.', 47),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Why is the tension the same on both sides of a smooth pulley?', 'The string is light and the pulley smooth, so nothing changes the tension along the string.', 48),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A 1000 kg car tows a 500 kg trailer. Driving force 3000 N, resistances 400 N (car) and 200 N (trailer). Find the tension.', 'Whole system: 3000 − 600 = 1500a, so a = 1.6 m s⁻². Trailer alone: T − 200 = 500 × 1.6, so T = 1000 N.', 49),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A 60 kg person stands in a lift accelerating upwards at 0.5 m s⁻². Find the reaction from the floor.', 'R − 60g = 60 × 0.5, so R = 588 + 30 = 618 N.', 50),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A resultant force (6i − 8j) N acts on a 2 kg particle. Find the acceleration and its magnitude.', 'a = F/m = 3i − 4j m s⁻², magnitude 5 m s⁻².', 51),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A ball is projected horizontally at 10 m s⁻¹ from 19.6 m above level ground. Find the time of flight and range.', '19.6 = 4.9t², so t = 2 s. Horizontal distance 10 × 2 = 20 m.', 52),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'For a given speed on level ground, which angle gives the greatest range?', '45°, since R = u² sin 2θ/g is greatest when sin 2θ = 1.', 53),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'How do you find the speed and direction of a projectile at time t?', 'Find the horizontal component u cos θ and the vertical component u sin θ − gt. Speed is √(vₓ² + vᵧ²) and the direction is arctan(vᵧ/vₓ) to the horizontal.', 54),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'State the Cartesian equation of a projectile''s trajectory.', 'y = x tan θ − gx²/(2u² cos²θ), from eliminating t.', 55),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Where does the weight of a uniform rod act?', 'At its midpoint.', 56),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A rod rests on two supports. What happens when it is on the point of tilting about one support?', 'The reaction at the other support is zero.', 57),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'A uniform 4 m plank of mass 20 kg rests on supports at its ends A and B. A 50 kg man stands 1 m from A. Find the reactions.', 'Moments about A: 4R_B = 20g × 2 + 50g × 1, so R_B = 22.5g ≈ 220.5 N. Then R_A = 70g − 22.5g = 47.5g ≈ 465.5 N.', 58),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'Which forces act on a uniform ladder resting against a smooth wall on rough ground?', 'Weight at the midpoint, normal reaction and friction at the ground, and a normal reaction at the wall perpendicular to it (no friction there).', 59),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'How do you find the moment of a force acting at an angle to a rod?', 'Moment = F × perpendicular distance = F d sin θ, where d is the distance along the rod and θ the angle between force and rod.', 60),
  ('Mathematics', 'AQA', 'alevel', '2.2', 'Mechanics', 'How do you find the centre of mass of a non-uniform rod?', 'Let the weight act at an unknown distance x from one end, then take moments to find x.', 61)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Mathematics' AND exam_board = 'AQA' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked;

-- ═══════════════════════════════════════════════════════════════════════
-- FURTHER MATHEMATICS — EDEXCEL A-LEVEL (9FM0), CORE PURE
-- ═══════════════════════════════════════════════════════════════════════

-- Two top-up cards are corrected here, in case flashcards/topup/paste/5-further-maths.sql
-- has already run. 'y = ln x from 1 to e rotated about the y-axis' did not say which
-- region is rotated (an explicit card replaces it below), and the r·n = d back was unclear.
DELETE FROM flashcards
WHERE subject = 'Further Mathematics' AND exam_board = 'Edexcel' AND level = 'alevel'
  AND topic_id = 'CP2.4' AND front = 'Find the volume when y = ln x from 1 to e is rotated about the y-axis.';

UPDATE flashcards SET back = 'A plane with normal vector n. Its perpendicular distance from the origin is |d|/|n|.'
WHERE subject = 'Further Mathematics' AND exam_board = 'Edexcel' AND level = 'alevel'
  AND topic_id = 'CP1.9' AND front = 'What does r·n = d mean geometrically?';

WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is i?', 'The imaginary unit, defined by i² = −1.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is a complex number?', 'A number of the form z = a + bi, where a and b are real.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What are Re(z) and Im(z) for z = 3 − 4i?', 'Re(z) = 3 and Im(z) = −4.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is the complex conjugate of z = a + bi?', 'z* = a − bi.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Simplify i³ and i⁴.', 'i³ = −i and i⁴ = 1.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Add (2 + 3i) + (4 − i).', '6 + 2i.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Multiply (2 + 3i)(1 − i).', '2 − 2i + 3i − 3i² = 5 + i.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is z z* for z = a + bi?', 'a² + b², which is always real and non-negative.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'How do you divide complex numbers?', 'Multiply the numerator and denominator by the conjugate of the denominator.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Calculate (3 + i)/(1 − i).', '(3 + i)(1 + i)/2 = (3 + 4i + i²)/2 = (2 + 4i)/2 = 1 + 2i.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Solve z² + 4 = 0.', 'z = ±2i.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Solve z² − 2z + 5 = 0.', 'z = (2 ± √(4 − 20))/2 = 1 ± 2i.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is special about the complex roots of a real polynomial?', 'They occur in conjugate pairs.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'If 2 + i is a root of a real quadratic, what is the quadratic?', 'Roots 2 ± i: z² − 4z + 5 = 0.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'When are two complex numbers equal?', 'When their real parts are equal and their imaginary parts are equal.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Find the square roots of 3 + 4i.', '(a + bi)² = 3 + 4i gives a² − b² = 3 and ab = 2, so ±(2 + i).', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is the modulus of z = a + bi?', '|z| = √(a² + b²).', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is the argument of z?', 'The angle θ between the positive real axis and the line to z, usually −π < θ ≤ π.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Find the modulus and argument of 1 + i.', '|z| = √2 and arg z = π/4.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Find the argument of −1 − √3 i.', '−2π/3.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is the modulus–argument form of z?', 'z = r(cos θ + i sin θ).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'How do moduli behave under multiplication?', '|z₁z₂| = |z₁||z₂|.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'How do arguments behave under multiplication?', 'arg(z₁z₂) = arg z₁ + arg z₂ (adjusted to the principal range).', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'How do moduli and arguments behave under division?', '|z₁/z₂| = |z₁|/|z₂| and arg(z₁/z₂) = arg z₁ − arg z₂.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Solve a cubic with a known real root: z³ − 1 = 0.', '(z − 1)(z² + z + 1) = 0, so z = 1 or z = −½ ± (√3/2)i.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is z + z* for z = a + bi?', '2a, which is real.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is z − z*?', '2bi, which is purely imaginary.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'What is (z*)*?', 'z.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Express 2(cos π/3 + i sin π/3) in the form a + bi.', '1 + √3 i.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Why can''t complex numbers be ordered like real numbers?', 'There is no consistent way to say which of two complex numbers is larger.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', '2 + i is a root of z³ − 3z² + z + 5 = 0. Find the other roots.', '2 − i is also a root, giving the factor z² − 4z + 5. Dividing leaves z + 1, so the roots are 2 ± i and −1.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', '2i is a root of z⁴ − 2z³ + 6z² − 8z + 8 = 0. Solve the equation.', '±2i give the factor z² + 4, and the quotient is z² − 2z + 2. The roots are ±2i and 1 ± i.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Solve z + 2z* = 6 − i.', 'With z = x + iy: 3x − iy = 6 − i, so x = 2, y = 1 and z = 2 + i.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'Find real a and b such that (a + bi)(2 − i) = 5.', 'a + bi = 5/(2 − i) = 5(2 + i)/5 = 2 + i, so a = 2 and b = 1.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.1', 'Complex Numbers', 'How do you find the other roots of a real polynomial given one complex root?', 'Its conjugate is also a root. Multiply the two linear factors to get a real quadratic factor, then divide to find what remains.', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What is an Argand diagram?', 'A diagram representing complex numbers as points, with the real part on the horizontal axis and the imaginary part on the vertical axis.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'How is z* shown on an Argand diagram?', 'As the reflection of z in the real axis.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What does |z − a| represent?', 'The distance from z to the point a on the Argand diagram.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Describe the locus |z − 2 − i| = 3.', 'A circle with centre (2, 1) and radius 3.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Describe the locus |z − 1| = |z + i|.', 'The perpendicular bisector of the points 1 and −i.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Describe the locus arg(z − 1) = π/4.', 'A half-line from (1, 0) at angle π/4 to the positive real axis, not including the point 1.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What does |z| < 2 represent?', 'The interior of a circle centred at the origin with radius 2.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Describe the region |z − 3| ≤ |z + 1|.', 'The points closer to 3 than to −1: Re(z) ≥ 1.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What does arg z = θ represent?', 'A half-line from the origin at angle θ.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'How is addition shown on an Argand diagram?', 'As vector addition (the parallelogram rule).', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'How is multiplication by i shown on an Argand diagram?', 'A rotation by π/2 anticlockwise about the origin.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What is the effect of multiplying by r(cos θ + i sin θ)?', 'An enlargement by scale factor r and a rotation by θ about the origin.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Find the maximum value of |z| if |z − 3 − 4i| = 2.', 'The distance to the centre is 5, so the maximum is 5 + 2 = 7.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Find the minimum value of |z| if |z − 3 − 4i| = 2.', '5 − 2 = 3.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'How do you convert a locus like |z − 1| = 2|z + 1| into Cartesian form?', 'Let z = x + iy, square both sides, and simplify, giving a circle (an Apollonius circle).', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What does arg((z − a)/(z − b)) = θ represent?', 'An arc of a circle through a and b, where the angle subtended by ab is θ.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What does arg((z − a)/(z − b)) = π/2 represent?', 'A semicircle with diameter ab.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'How do you shade a region like π/6 ≤ arg z ≤ π/3?', 'Shade between the two half-lines from the origin at those angles.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'How is the modulus shown on an Argand diagram?', 'As the distance from the origin to the point.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What locus is |z − a| = k|z − b| for k ≠ 1?', 'A circle.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Where are the roots of z² + 2z + 5 = 0 on an Argand diagram?', 'At −1 + 2i and −1 − 2i, symmetric about the real axis.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Describe |z + 2i| = 1.', 'A circle with centre −2i (0, −2) and radius 1.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'How do you find where two loci intersect?', 'Convert both to Cartesian equations and solve simultaneously, or use geometry.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What does Re(z) > 2 represent?', 'The region to the right of the line x = 2.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What does Im(z) = −1 represent?', 'A horizontal line through −i.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What is the geometric meaning of |z₁ − z₂|?', 'The distance between z₁ and z₂.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'How can the triangle inequality be written for complex numbers?', '|z₁ + z₂| ≤ |z₁| + |z₂|.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Describe the locus |z| = |z − 4|.', 'The line Re(z) = 2.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'What shape do the n-th roots of unity form on an Argand diagram?', 'A regular n-sided polygon inscribed in the unit circle.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'How do you find the greatest arg z for z on a circle not containing the origin?', 'Draw the tangent from the origin to the circle and use right-angled triangle trigonometry.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Write −√3 + i in modulus-argument form.', '|z| = 2 and arg z = 5π/6 (second quadrant), so z = 2(cos 5π/6 + i sin 5π/6).', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Find z satisfying both |z − 4| = |z| and arg z = π/4.', 'The first locus is Re(z) = 2 and the second is the half-line y = x, x > 0. So z = 2 + 2i.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Describe the locus arg(z + 2) = −π/2.', 'A half-line from −2 pointing vertically downwards (parallel to the negative imaginary axis), not including −2 itself.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Multiply 2(cos π/3 + i sin π/3) by 3(cos π/6 + i sin π/6).', 'Multiply the moduli and add the arguments: 6(cos π/2 + i sin π/2) = 6i.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.2', 'Argand Diagrams', 'Why is the point a excluded from the locus arg(z − a) = θ?', 'arg 0 is undefined, so z = a has no argument and cannot satisfy the equation.', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is Σ r from r = 1 to n?', 'n(n + 1)/2.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is Σ r² from r = 1 to n?', 'n(n + 1)(2n + 1)/6.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is Σ r³ from r = 1 to n?', 'n²(n + 1)²/4.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is Σ 1 from r = 1 to n?', 'n.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Evaluate Σ r² from r = 1 to 10.', '10 × 11 × 21/6 = 385.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Find Σ (2r − 1) from r = 1 to n.', 'n(n + 1) − n = n².', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Find Σ r(r + 1) from r = 1 to n.', 'Σr² + Σr = n(n + 1)(n + 2)/3.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'How do you evaluate Σ from r = 11 to 20?', 'Σ from 1 to 20 minus Σ from 1 to 10.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is the method of differences?', 'Writing each term as f(r) − f(r + 1) so that most terms cancel when summed.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Use the method of differences to sum Σ 1/(r(r + 1)).', '1/(r(r + 1)) = 1/r − 1/(r + 1), so the sum from 1 to n is 1 − 1/(n + 1).', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Find Σ 1/(r(r + 2)) from r = 1 to n.', '½ Σ (1/r − 1/(r + 2)) = ½(3/2 − 1/(n + 1) − 1/(n + 2)).', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is a telescoping series?', 'A series in which consecutive terms cancel, leaving only a few terms.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is the sum to infinity of Σ 1/(r(r + 1))?', '1.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'How do you prove a summation formula?', 'Using the standard results, the method of differences, or proof by induction.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is Σ (ar + b)?', 'aΣr + bn.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Express Σ r(r − 1) in terms of n.', 'Σr² − Σr = (n − 1)n(n + 1)/3.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Evaluate Σ r³ from r = 1 to 5.', '25 × 36/4 = 225.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is the relationship between Σ r³ and Σ r?', 'Σ r³ = (Σ r)².', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Why must care be taken with the lower limit when using the method of differences?', 'The surviving terms depend on the limits; write out the first and last few terms.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'How are partial fractions useful for series?', 'They split a term into differences that telescope.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is sigma notation?', 'Σ f(r) from r = a to b means f(a) + f(a + 1) + … + f(b).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Can a divergent series have a finite partial sum?', 'Yes, every partial sum is finite, but the sum to infinity doesn''t exist.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Find Σ (r + 1)² from r = 1 to n.', 'Σr² + 2Σr + n = n(n + 1)(2n + 1)/6 + n(n + 1) + n.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is Σ from r = 1 to n of r(r + 1)(r + 2)?', 'n(n + 1)(n + 2)(n + 3)/4.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Show that Σ from 1 to n of (r³ − r) = n(n + 1)(n − 1)(n + 2)/4.', 'n²(n + 1)²/4 − n(n + 1)/2 = n(n + 1)/4 × (n(n + 1) − 2) = n(n + 1)(n − 1)(n + 2)/4.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is the sum of the first n odd cubes?', 'n²(2n² − 1).', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What does convergence mean for a series?', 'The partial sums approach a finite limit as n → ∞.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is the harmonic series and does it converge?', 'Σ 1/r; it diverges.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'How do you sum Σ f(r) − f(r − 1) from 1 to n?', 'It telescopes to f(n) − f(0).', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'What is the general strategy for summing a polynomial in r?', 'Expand, then use the standard results for Σr, Σr², Σr³ and Σ1.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Show that Σ(6r² + 2r) from r = 1 to n equals 2n(n + 1)².', '6 × n(n + 1)(2n + 1)/6 + 2 × n(n + 1)/2 = n(n + 1)(2n + 1) + n(n + 1) = n(n + 1)(2n + 2) = 2n(n + 1)².', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Evaluate Σ(3r − 1) from r = 1 to 20.', '3 × (20 × 21/2) − 20 = 630 − 20 = 610.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Find Σr² from r = n + 1 to 2n.', 'Σ to 2n minus Σ to n: 2n(2n + 1)(4n + 1)/6 − n(n + 1)(2n + 1)/6 = n(2n + 1)(7n + 1)/6.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.3', 'Series', 'Why can Σ k from r = 1 to n not be written as k?', 'The constant k is added n times, so the sum is kn.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'For ax² + bx + c = 0 with roots α, β, what are α + β and αβ?', 'α + β = −b/a and αβ = c/a.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'For ax³ + bx² + cx + d = 0, what are Σα, Σαβ and αβγ?', 'Σα = −b/a, Σαβ = c/a, αβγ = −d/a.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'For a quartic ax⁴ + bx³ + cx² + dx + e = 0, what is the product of the roots?', 'αβγδ = e/a.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Express α² + β² in terms of α + β and αβ.', '(α + β)² − 2αβ.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Express α³ + β³ in terms of α + β and αβ.', '(α + β)³ − 3αβ(α + β).', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Express 1/α + 1/β in terms of α + β and αβ.', '(α + β)/αβ.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Express α² + β² + γ² for a cubic.', '(Σα)² − 2Σαβ.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'How do you find an equation whose roots are 2α and 2β?', 'Substitute x = w/2 into the original equation.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'How do you find an equation whose roots are α + 1, β + 1?', 'Substitute x = w − 1 into the original equation.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'How do you find an equation with roots α², β² using substitution?', 'Substitute x = √w, rearrange so √w terms are on one side, and square.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'The roots of x² − 5x + 3 = 0 are α, β. Find α² + β².', '25 − 6 = 19.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'The roots of 2x³ − 3x² + x − 4 = 0 are α, β, γ. Find αβγ.', '−(−4)/2 = 2.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Find the quadratic with roots α + β and αβ given α + β = 3, αβ = 2.', 'Roots 3 and 2: x² − 5x + 6 = 0.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'If one root of x³ − 6x² + 11x − 6 = 0 is 1, find the others.', '(x − 1)(x² − 5x + 6), so 2 and 3.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'What does it mean if a cubic''s roots form an arithmetic sequence?', 'They can be written a − d, a, a + d, and Σα = 3a.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Why do real polynomials have complex roots in conjugate pairs?', 'Taking the conjugate of p(z) = 0 gives p(z*) = 0, because the coefficients are real.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'A real cubic has roots 2 and 1 + i. Find the cubic.', 'Roots 2, 1 ± i: (x − 2)(x² − 2x + 2) = x³ − 4x² + 6x − 4.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'How many real roots can a real cubic have?', 'One or three (counting repeated roots).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'How many complex (non-real) roots can a real quartic have?', '0, 2 or 4.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'What is Σα for x⁴ − 2x³ + x − 7 = 0?', '2.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'What is Σαβγ for a quartic ax⁴ + bx³ + cx² + dx + e?', '−d/a.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Find α³ + β³ if α + β = 2 and αβ = −1.', '8 − 3(−1)(2) = 14.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'How do you find 1/α + 1/β + 1/γ for a cubic?', 'Σαβ/αβγ.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'What does a repeated root mean for the graph?', 'The graph touches the x-axis at that point.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'If x = 2 + 3i is a root of a real polynomial, what else must be?', '2 − 3i.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'How can the sum and product of roots check a solution?', 'Compare the computed roots'' sum and product with −b/a and c/a.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'What substitution gives roots 1/α, 1/β, 1/γ?', 'Substitute x = 1/w (this reverses the coefficients).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Find the equation with roots 1/α, 1/β if α, β are roots of 2x² + 3x − 1 = 0.', 'Reverse the coefficients: −w² + 3w + 2 = 0, i.e. w² − 3w − 2 = 0.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'How many roots does a polynomial of degree n have?', 'Exactly n roots in the complex numbers, counting multiplicity.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'What is the Fundamental Theorem of Algebra?', 'Every non-constant polynomial has at least one complex root.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'The roots of x³ + 2x² − x + 3 = 0 are α, β, γ. Find α² + β² + γ².', 'Σα = −2 and Σαβ = −1, so (Σα)² − 2Σαβ = 4 + 2 = 6.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Find the equation with roots 2α, 2β, 2γ, where α, β, γ are the roots of x³ + 2x² − x + 3 = 0.', 'Substitute x = w/2 and multiply by 8: w³ + 4w² − 4w + 24 = 0.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Express α³ + β³ + γ³ in terms of the coefficients of a cubic.', '(Σα)³ − 3(Σα)(Σαβ) + 3αβγ.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'For a quartic, express α² + β² + γ² + δ² using Σα and Σαβ.', '(Σα)² − 2Σαβ.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.4', 'Roots of Polynomials', 'Find the equation whose roots are each one less than those of x³ − 6x² + 11x − 6 = 0.', 'Substitute x = w + 1. The roots 1, 2, 3 become 0, 1, 2, giving w³ − 3w² + 2w = 0.', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the volume of revolution about the x-axis?', 'V = π ∫ y² dx between the limits.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the volume of revolution about the y-axis?', 'V = π ∫ x² dy between the y-limits.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = x from 0 to 3 is rotated about the x-axis.', 'π ∫₀³ x² dx = 9π (a cone).', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = √x from 0 to 4 is rotated about the x-axis.', 'π ∫₀⁴ x dx = 8π.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = x² from 0 to 1 is rotated about the x-axis.', 'π ∫₀¹ x⁴ dx = π/5.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How do you find the volume between two curves rotated about the x-axis?', 'V = π ∫ (y₁² − y₂²) dx, where y₁ is the outer curve.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Why is it not π ∫ (y₁ − y₂)² dx?', 'The solid is a washer: the volume is the outer solid minus the inner solid.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How do you rotate y = x² about the y-axis between y = 0 and y = 4?', 'x² = y, so V = π ∫₀⁴ y dy = 8π.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the volume of a sphere derived by rotation?', 'Rotate x² + y² = r² about the x-axis: π ∫₋ᵣʳ (r² − x²) dx = (4/3)πr³.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the volume of a cone derived by rotation?', 'Rotate y = (r/h)x from 0 to h: π ∫ (r²/h²)x² dx = (1/3)πr²h.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How can volumes of revolution model real objects?', 'E.g. vases, bottles and bowls can be modelled by rotating curves.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What assumption is made when modelling an object with a volume of revolution?', 'The object is perfectly symmetrical about its axis and the curve accurately describes its profile.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = eˣ from 0 to 1 is rotated about the x-axis.', 'π ∫₀¹ e^(2x) dx = (π/2)(e² − 1).', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = 1/x from 1 to 2 is rotated about the x-axis.', 'π ∫₁² x⁻² dx = π/2.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What must you do before rotating about the y-axis?', 'Rearrange to make x² the subject in terms of y, and use y-limits.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = sin x from 0 to π is rotated about the x-axis.', 'π ∫₀^π sin²x dx = π²/2.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How do you find the volume of a solid with a hole?', 'Subtract the volume of the hole (inner solid) from the outer solid.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What are the units of a volume of revolution?', 'Cubic units.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the volume of a cylinder by rotation?', 'Rotate y = r from 0 to h about the x-axis: π ∫₀ʰ r² dx = πr²h.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How do you find the limits for the region between y = x and y = x²?', 'Solve x = x²: x = 0 and x = 1.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when the region between y = x and y = x² is rotated about the x-axis.', 'π ∫₀¹ (x² − x⁴) dx = π(1/3 − 1/5) = 2π/15.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What if the curve crosses the axis of rotation?', 'y² is always positive, so the volume formula still works, but check the region carefully.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How can a volume of revolution be scaled to model a real object?', 'Multiply by the cube of the scale factor, or use scaled units.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Why might a model underestimate a real vase''s volume?', 'The curve may not match the real shape exactly, or the wall thickness may be ignored.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What volume is generated by rotating y = 2 between x = 1 and x = 3?', 'A cylinder: π × 4 × 2 = 8π.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when y = x³ from 0 to 1 is rotated about the y-axis.', 'x = y^(1/3), x² = y^(2/3): π ∫₀¹ y^(2/3) dy = 3π/5.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'What is the washer method?', 'Finding the volume of a solid with a hole by subtracting inner from outer volumes.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'How do you find the volume of a region bounded by a curve and a line not on an axis?', 'Find the intersection points, then subtract the volume under the line from the volume under the curve.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Which integral gives volume about the x-axis for y = f(x)?', 'π ∫ [f(x)]² dx.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Why is volume of revolution an application of integration?', 'The solid is split into thin discs of volume πy² δx, which are summed as δx → 0.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when the region under y = x² + 1 from x = 0 to x = 1 is rotated 2π about the x-axis.', 'π∫(x⁴ + 2x² + 1)dx from 0 to 1 = π(1/5 + 2/3 + 1) = 28π/15.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Find the volume when the region between y = x², the y-axis, y = 1 and y = 4 is rotated about the y-axis.', 'x² = y, so π∫y dy from 1 to 4 = π(16 − 1)/2 = 15π/2.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.5', 'Volumes of Revolution', 'Which rotations does Edexcel Core Pure 1 include for volumes of revolution?', 'Rotations through 2π about the x-axis and about the y-axis, of regions bounded by curves given in Cartesian form. Parametric curves follow in Core Pure 2.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the order of a matrix?', 'The number of rows × the number of columns.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'When can two matrices be multiplied?', 'When the number of columns in the first equals the number of rows in the second.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Is matrix multiplication commutative?', 'No; in general AB ≠ BA.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Is matrix multiplication associative?', 'Yes: (AB)C = A(BC).', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the identity matrix I?', 'A square matrix with 1s on the leading diagonal and 0s elsewhere; AI = IA = A.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the determinant of a 2×2 matrix (a b; c d)?', 'ad − bc.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the inverse of a 2×2 matrix (a b; c d)?', '(1/(ad − bc)) × (d −b; −c a).', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is a singular matrix?', 'A matrix with determinant zero, which has no inverse.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is (AB)⁻¹?', 'B⁻¹A⁻¹.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How do you find the determinant of a 3×3 matrix?', 'Expand along a row or column using cofactors: a(ei − fh) − b(di − fg) + c(dh − eg).', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What does the determinant of a transformation matrix represent?', 'The area (2D) or volume (3D) scale factor; a negative value means orientation is reversed.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How can matrices solve simultaneous equations?', 'Write as AX = B, then X = A⁻¹B if A is non-singular.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What does det A = 0 mean for a system of 3 equations?', 'There is no unique solution: either no solutions (inconsistent) or infinitely many.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How do three planes with no unique solution appear geometrically?', 'As a sheaf (common line), a prism (no common point), or with parallel planes.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is det(AB)?', 'det A × det B.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the transpose of a matrix?', 'The matrix formed by swapping rows and columns, Aᵀ.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How do you find the inverse of a 3×3 matrix?', 'Find the matrix of cofactors, transpose it (adjugate), then divide by the determinant.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is the zero matrix?', 'A matrix in which every element is 0.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Multiply (1 2; 3 4)(0 1; 1 0).', '(2 1; 4 3).', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Find the determinant of (3 1; 5 2).', '6 − 5 = 1.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Find the inverse of (3 1; 5 2).', '(2 −1; −5 3).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'For what value of k is (k 2; 3 6) singular?', '6k − 6 = 0, so k = 1.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is A² for a matrix A?', 'A × A (only defined for square matrices).', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What does it mean if AB = I?', 'B is the inverse of A (and A is the inverse of B).', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How is a system of linear equations consistent?', 'When it has at least one solution.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is a minor in a 3×3 determinant?', 'The determinant of the 2×2 matrix left after deleting a row and column.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is a cofactor?', 'A minor multiplied by (−1)^(i+j).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'If det A = 3, what is det(2A) for a 3×3 matrix?', '2³ × 3 = 24.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'If det A = 5, what is det(A⁻¹)?', '1/5.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'How do you check a matrix inverse is correct?', 'Multiply by the original matrix and check the result is I.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Find the inverse of the diagonal matrix with entries 1, 2, 3.', 'The diagonal matrix with entries 1, 1/2, 1/3.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'Find the determinant of (2 1 0; 1 3 1; 0 1 2).', '2(6 − 1) − 1(2 − 0) + 0 = 8.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'For which k is (1 2 k; 0 1 1; 2 0 1) singular?', 'det = 1(1) − 2(0 − 2) + k(0 − 2) = 5 − 2k, so k = 5/2.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'What is (AB)ᵀ?', 'BᵀAᵀ — the order reverses, just as for inverses.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.6', 'Matrices', 'When det = 0 for three planes, how do you tell a sheaf from a prism?', 'Eliminate one variable from pairs of equations. If the two resulting equations are consistent the planes meet in a line (sheaf). If they contradict, there is no common point (a prism, unless two planes are parallel).', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What transformation does (1 0; 0 −1) represent?', 'A reflection in the x-axis.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What transformation does (−1 0; 0 1) represent?', 'A reflection in the y-axis.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What transformation does (0 1; 1 0) represent?', 'A reflection in the line y = x.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents an anticlockwise rotation by θ about the origin?', '(cos θ −sin θ; sin θ cos θ).', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents an enlargement by scale factor k about the origin?', '(k 0; 0 k).', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a stretch parallel to the x-axis, scale factor k?', '(k 0; 0 1).', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does the matrix (1 k; 0 1) represent?', 'A shear with the x-axis invariant: each point moves parallel to the x-axis by k times its y-coordinate.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you find the image of a point under a transformation?', 'Multiply the transformation matrix by the position vector of the point.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you find the matrix of a transformation?', 'Find the images of the unit vectors i and j (and k); these form the columns.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is the matrix for a combined transformation "A then B"?', 'BA (the first transformation is on the right).', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is an invariant point?', 'A point that maps to itself under a transformation.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is an invariant line?', 'A line where every point on it maps to a point on the same line.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is a line of invariant points?', 'A line where every point maps to itself.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you find invariant points of a matrix M?', 'Solve M(x, y) = (x, y).', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you find invariant lines y = mx + c?', 'Map a general point (x, mx + c) and require the image to satisfy the same equation, for all x.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is the area of an image under transformation M?', '|det M| × original area.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does a negative determinant tell you about a transformation?', 'It reverses orientation (includes a reflection).', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a reflection in y = −x?', '(0 −1; −1 0).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a rotation of 90° anticlockwise about the origin?', '(0 −1; 1 0).', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a rotation of 180° about the origin?', '(−1 0; 0 −1).', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a rotation about the z-axis in 3D?', '(cos θ −sin θ 0; sin θ cos θ 0; 0 0 1).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a reflection in the plane z = 0?', '(1 0 0; 0 1 0; 0 0 −1).', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'How do you reverse a transformation?', 'Apply the inverse matrix.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'Why is a singular matrix transformation not reversible?', 'It collapses the plane onto a line or point, so information is lost.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does a rotation matrix''s determinant equal?', '1.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does a reflection matrix''s determinant equal?', '−1.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'Find the image of (2, 3) under (1 2; 0 1).', '(2 + 6, 3) = (8, 3).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What does (2 0; 0 3) do to a unit square''s area?', 'It multiplies it by 6.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is the matrix for a rotation of θ clockwise?', '(cos θ sin θ; −sin θ cos θ).', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What is a shear''s effect on area?', 'None: a shear has determinant 1.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents reflection in the line y = x tan θ?', '(cos 2θ sin 2θ; sin 2θ −cos 2θ).', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What matrix represents a rotation of θ about the x-axis in 3D?', '(1 0 0; 0 cos θ −sin θ; 0 sin θ cos θ), anticlockwise looking towards the origin from the positive x-axis.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'Find the invariant lines through the origin for (2 1; 1 2).', '(x, mx) maps to (2x + mx, x + 2mx). Requiring x + 2mx = m(2x + mx) gives m² = 1, so y = x and y = −x.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'A triangle of area 5 is transformed by (3 1; 2 4). Find the image area.', 'det = 12 − 2 = 10, so the area is 50.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.7', 'Linear Transformations', 'What two properties define a linear transformation?', 'T(a + b) = T(a) + T(b) and T(ka) = kT(a). So the origin is fixed and straight lines map to straight lines.', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What are the steps of proof by induction?', 'Basis (show true for n = 1), assumption (assume true for n = k), inductive step (show true for n = k + 1), conclusion.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What should the conclusion of an induction proof state?', 'If true for n = k, it is true for n = k + 1; since it is true for n = 1, it is true for all positive integers n.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove Σ r from 1 to n = n(n + 1)/2 by induction: what is the inductive step?', 'Assume Σ to k = k(k + 1)/2. Then Σ to k + 1 = k(k + 1)/2 + (k + 1) = (k + 1)(k + 2)/2.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for divisibility?', 'Show f(1) is divisible by m, then write f(k + 1) in terms of f(k) plus a multiple of m.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove 6ⁿ − 1 is divisible by 5 for n ≥ 1.', 'n = 1: 5. Assume 6ᵏ − 1 = 5m. Then 6^(k+1) − 1 = 6(6ᵏ − 1) + 5 = 30m + 5, divisible by 5.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove 3^(2n) − 1 is divisible by 8.', 'n = 1: 8. Assume 9ᵏ − 1 = 8m. Then 9^(k+1) − 1 = 9(9ᵏ − 1) + 8 = 72m + 8.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for matrices?', 'Show the formula for Mⁿ holds for n = 1, then multiply Mᵏ by M to get the formula for M^(k+1).', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove by induction that (1 1; 0 1)ⁿ = (1 n; 0 1).', 'n = 1 is true. Assume true for k; then (1 k; 0 1)(1 1; 0 1) = (1 k + 1; 0 1).', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for recurrence relations?', 'Show the closed form matches u₁, then use the recurrence with the assumption to show it holds for u_(k+1).', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove uₙ = 2ⁿ − 1 if u₁ = 1, u_(n+1) = 2uₙ + 1.', 'n = 1: 1. Assume u_k = 2ᵏ − 1. Then u_(k+1) = 2(2ᵏ − 1) + 1 = 2^(k+1) − 1.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for derivatives?', 'Show the formula for the n-th derivative holds for n = 1, then differentiate the k-th to get the (k + 1)-th.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove that d^n/dx^n (x eˣ) = (x + n)eˣ.', 'n = 1: (x + 1)eˣ. Assume true for k; differentiating (x + k)eˣ gives (x + k + 1)eˣ.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Why is the basis step necessary?', 'Without it, the chain of implications has no starting point.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Why is the inductive step alone not enough?', 'It only shows "if true for k then true for k + 1", not that it is ever true.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Can induction start from a value other than 1?', 'Yes; the basis can be any integer, and the result holds for all integers from there.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What is a common error in induction proofs?', 'Assuming the result for k + 1 instead of deriving it, or omitting the conclusion.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove Σ r² = n(n + 1)(2n + 1)/6: what must be shown in the inductive step?', 'k(k + 1)(2k + 1)/6 + (k + 1)² = (k + 1)(k + 2)(2k + 3)/6.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove that 2ⁿ > n for all n ≥ 1.', 'n = 1: 2 > 1. Assume 2ᵏ > k. Then 2^(k+1) = 2 × 2ᵏ > 2k ≥ k + 1 for k ≥ 1.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How is induction used for inequalities?', 'Use the assumption and then show the next case satisfies the inequality, often using extra algebraic steps.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove n³ − n is divisible by 6 using induction.', 'n = 1: 0. (k + 1)³ − (k + 1) = (k³ − k) + 3k(k + 1); k(k + 1) is even, so 3k(k + 1) is a multiple of 6.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What is the key idea of induction?', 'Like dominoes: if the first falls and each one knocks over the next, all fall.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What is proof by exhaustion compared with induction?', 'Exhaustion checks a finite number of cases; induction proves infinitely many.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Can induction prove statements about all real numbers?', 'No, only about integers (or well-ordered sets).', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove 7ⁿ − 3ⁿ is divisible by 4.', 'n = 1: 4. 7^(k+1) − 3^(k+1) = 7(7ᵏ − 3ᵏ) + 4 × 3ᵏ, divisible by 4.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What should you write for the assumption step?', '"Assume the statement is true for n = k", then write out the statement with k.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'How do you prove a sum formula for Σ r(r + 1)?', 'Basis with n = 1, assume for k, add (k + 1)(k + 2), and factorise.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Why must the final result be clearly shown to match the formula with k + 1?', 'To demonstrate that the statement holds for n = k + 1.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'What does "for all n ∈ ℤ⁺" mean?', 'For all positive integers n.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove that 4ⁿ + 6n − 1 is divisible by 9.', 'n = 1: 9. f(k + 1) − 4f(k) = 6(k + 1) − 1 − 24k + 4 = −18k + 9, a multiple of 9.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Why might f(k + 1) − f(k) be useful in divisibility proofs?', 'If it is divisible by m and f(k) is, then so is f(k + 1).', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Which contexts does Edexcel Core Pure 1 name for proof by induction?', 'Sums of series, divisibility and powers of matrices.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove that 5ⁿ + 3 is divisible by 4 for n ≥ 1.', 'n = 1: 8. Assume 5ᵏ + 3 = 4m. Then 5^(k+1) + 3 = 5(5ᵏ + 3) − 12 = 20m − 12 = 4(5m − 3).', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove Σ1/(r(r + 1)) = n/(n + 1): what is the inductive step?', 'k/(k + 1) + 1/((k + 1)(k + 2)) = (k² + 2k + 1)/((k + 1)(k + 2)) = (k + 1)/(k + 2).', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.8', 'Proof by Induction', 'Prove that (2 0; 0 3)ⁿ = (2ⁿ 0; 0 3ⁿ).', 'True for n = 1. Assume it for k, then multiply by (2 0; 0 3) to get (2^(k+1) 0; 0 3^(k+1)). So it holds for all n ≥ 1.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the vector equation of a line?', 'r = a + λb, where a is a point on the line and b is the direction vector.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the Cartesian equation of a line?', '(x − a₁)/b₁ = (y − a₂)/b₂ = (z − a₃)/b₃.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the scalar (dot) product?', 'a·b = a₁b₁ + a₂b₂ + a₃b₃ = |a||b| cos θ.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What does a·b = 0 mean?', 'The vectors are perpendicular.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the angle between two lines?', 'Use the dot product of their direction vectors: cos θ = (b₁·b₂)/(|b₁||b₂|).', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the vector equation of a plane?', 'r = a + λb + μc, or r·n = a·n.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the Cartesian equation of a plane?', 'n₁x + n₂y + n₃z = d, where n is the normal.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is a normal vector to a plane?', 'A vector perpendicular to the plane.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the angle between a line and a plane?', 'Find the angle between the direction and the normal, then subtract from 90°.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the angle between two planes?', 'Find the angle between their normals.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find where a line meets a plane?', 'Substitute the line''s parametric form into the plane equation and solve for λ.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you tell if two lines are skew?', 'They are not parallel and don''t intersect.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the intersection of two lines?', 'Set the vector equations equal and solve for the parameters, checking all three components.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the vector (cross) product?', 'a × b, a vector perpendicular to both a and b with magnitude |a||b| sin θ.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you calculate a × b?', '(a₂b₃ − a₃b₂, a₃b₁ − a₁b₃, a₁b₂ − a₂b₁).', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the normal to a plane containing vectors b and c?', 'Calculate b × c.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the perpendicular distance from a point to a plane?', '|ax₀ + by₀ + cz₀ − d|/√(a² + b² + c²).', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the shortest distance between skew lines?', '|(a₂ − a₁)·n|/|n|, where n = b₁ × b₂.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the shortest distance from a point to a line?', 'Find the foot of the perpendicular (where (p − r)·b = 0), then find the distance.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the area of a triangle using vectors?', '½|AB × AC|.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the volume of a parallelepiped?', '|a·(b × c)| (the scalar triple product).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the line of intersection of two planes?', 'It has direction n₁ × n₂; find a point by solving the equations with one variable fixed.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the reflection of a point in a plane?', 'Find the foot of the perpendicular, then go the same distance beyond it.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'When are two planes parallel?', 'When their normals are parallel.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What does r·n = d mean geometrically?', 'A plane with normal vector n. Its perpendicular distance from the origin is |d|/|n|.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'Find the angle between (1, 2, 2) and (2, −1, 2).', 'Dot product = 2 − 2 + 4 = 4; |a| = |b| = 3; cos θ = 4/9, θ ≈ 63.6°.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you check a point lies on a line?', 'Find a λ that satisfies all three components.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is a unit normal?', 'A normal vector divided by its magnitude.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'Find the Cartesian equation of the plane with normal (2, −1, 3) through (1, 1, 1).', '2x − y + 3z = 4.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'What is the scalar product of a vector with itself?', 'a·a = |a|².', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'Find where r = (1, 0, 2) + λ(2, 1, −1) meets the plane x + y + z = 6.', '(1 + 2λ) + λ + (2 − λ) = 3 + 2λ = 6, so λ = 1.5 and the point is (4, 1.5, 0.5).', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'Find the distance from (1, 2, 3) to the plane 2x − y + 2z = 1.', '|2 − 2 + 6 − 1|/√(4 + 1 + 4) = 5/3.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'Find the acute angle between the planes x + y = 1 and y + z = 2.', 'Normals (1, 1, 0) and (0, 1, 1): cos θ = 1/(√2 × √2) = ½, so θ = 60°.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'Write r = (1, 2, 3) + λ(2, −1, 4) in Cartesian form.', '(x − 1)/2 = (y − 2)/(−1) = (z − 3)/4.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP1.9', 'Vectors (Core Pure + FP1)', 'How do you find the distance between two parallel lines?', 'Take a point on one line and find its perpendicular distance to the other, using the foot of the perpendicular.', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is Euler''s formula?', 'e^(iθ) = cos θ + i sin θ.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the exponential form of a complex number?', 'z = re^(iθ).', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is e^(iπ)?', '−1.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'State de Moivre''s theorem.', '[r(cos θ + i sin θ)]ⁿ = rⁿ(cos nθ + i sin nθ).', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Calculate (1 + i)⁸ using de Moivre.', '(√2)⁸(cos 2π + i sin 2π) = 16.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How can de Moivre express cos 3θ in terms of cos θ?', 'Expand (cos θ + i sin θ)³ and take the real part: cos 3θ = 4cos³θ − 3cos θ.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Express sin 3θ in terms of sin θ.', 'sin 3θ = 3 sin θ − 4 sin³θ.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is z + 1/z if z = e^(iθ)?', '2 cos θ.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is z − 1/z if z = e^(iθ)?', '2i sin θ.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is zⁿ + 1/zⁿ if z = e^(iθ)?', '2 cos nθ.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How do you express cos⁴θ in terms of multiple angles?', 'Expand (z + 1/z)⁴ = 16cos⁴θ, giving cos⁴θ = (cos 4θ + 4cos 2θ + 3)/8.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What are the n-th roots of unity?', 'The solutions of zⁿ = 1: z = e^(2πki/n) for k = 0, 1, …, n − 1.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the sum of the n-th roots of unity (n > 1)?', '0.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Find the cube roots of unity.', '1, e^(2πi/3), e^(4πi/3), i.e. 1 and −½ ± (√3/2)i.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'If ω is a primitive cube root of unity, what is 1 + ω + ω²?', '0.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Solve z³ = 8i.', '8i = 8e^(iπ/2), so z = 2e^(i(π/6 + 2πk/3)), k = 0, 1, 2: 2e^(iπ/6), 2e^(i5π/6), 2e^(−iπ/2).', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How do you solve zⁿ = w in general?', 'Write w = re^(iθ); then z = r^(1/n) e^(i(θ + 2πk)/n), k = 0, …, n − 1.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How are the n-th roots of a complex number arranged?', 'Equally spaced around a circle of radius r^(1/n), separated by 2π/n.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How do you sum a series like Σ cos kθ using complex numbers?', 'Sum the geometric series Σ e^(ikθ) and take the real part.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the conjugate of re^(iθ)?', 're^(−iθ).', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is e^(iθ) × e^(iφ)?', 'e^(i(θ + φ)).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Express −2 in exponential form.', '2e^(iπ).', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the modulus of e^(iθ)?', '1.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Use de Moivre to find (cos π/6 + i sin π/6)⁶.', 'cos π + i sin π = −1.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How can roots of unity solve (z + 1)⁵ = z⁵?', 'Divide: ((z + 1)/z)⁵ = 1, so (z + 1)/z = ω, the fifth roots of unity (excluding 1), and solve for z.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What does de Moivre''s theorem say for negative n?', 'It also holds: (cos θ + i sin θ)^(−n) = cos nθ − i sin nθ.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How is cos θ written in exponential form?', 'cos θ = (e^(iθ) + e^(−iθ))/2.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'How is sin θ written in exponential form?', 'sin θ = (e^(iθ) − e^(−iθ))/(2i).', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What is the principal argument?', 'The argument θ with −π < θ ≤ π.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'What geometric transformation does multiplying by e^(iπ/3) represent?', 'A rotation by π/3 anticlockwise about the origin.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Find the fourth roots of −16.', '−16 = 16e^(iπ), so z = 2e^(i(π/4 + kπ/2)) for k = 0, 1, 2, 3. That is ±√2 ± √2i.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Express cos 4θ in powers of cos θ.', '8cos⁴θ − 8cos²θ + 1, from the real part of (cos θ + i sin θ)⁴.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Write (√3 + i)⁶ in the form a + bi.', '√3 + i = 2e^(iπ/6), so the power is 64e^(iπ) = −64.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'If ω = e^(2πi/5), find 1 + ω + ω² + ω³ + ω⁴.', '0 — the sum of the fifth roots of unity.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.1', 'Complex Numbers (Further)', 'Write 1 − i in exponential form.', '√2 e^(−iπ/4).', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is a Maclaurin series?', 'f(x) = f(0) + f''(0)x + f''''(0)x²/2! + f''''''(0)x³/3! + …', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for eˣ?', '1 + x + x²/2! + x³/3! + …, valid for all x.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for sin x?', 'x − x³/3! + x⁵/5! − …, valid for all x.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for cos x?', '1 − x²/2! + x⁴/4! − …, valid for all x.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for ln(1 + x)?', 'x − x²/2 + x³/3 − …, valid for −1 < x ≤ 1.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the Maclaurin series for (1 + x)ⁿ?', '1 + nx + n(n − 1)x²/2! + …, valid for |x| < 1 (non-integer n).', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the Maclaurin series for e^(2x) up to x³.', '1 + 2x + 2x² + (4/3)x³.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for sin 3x up to x³.', '3x − (27/6)x³ = 3x − 4.5x³.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for eˣ sin x up to x³.', '(1 + x + x²/2)(x − x³/6) = x + x² + x³/3 + …', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for ln(1 − x) up to x³.', '−x − x²/2 − x³/3.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the validity of ln(1 − x)''s series?', '−1 ≤ x < 1.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How can a Maclaurin series approximate a value?', 'Substitute a small x into the first few terms, e.g. e^0.1 ≈ 1 + 0.1 + 0.005.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How can series find limits?', 'Replace functions with their series and simplify, e.g. lim (sin x)/x = 1.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find lim (x→0) of (1 − cos x)/x².', '(x²/2 − …)/x² → 1/2.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find lim (x→0) of (eˣ − 1)/x.', '(x + x²/2 + …)/x → 1.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is a Taylor series?', 'An expansion about x = a: f(x) = f(a) + f''(a)(x − a) + f''''(a)(x − a)²/2! + …', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Why are Taylor series about x = a useful?', 'They give good approximations near x = a, where the Maclaurin series might not converge or be accurate.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the Taylor series of ln x about x = 1 up to (x − 1)².', '(x − 1) − (x − 1)²/2.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Why does ln x not have a Maclaurin series?', 'ln x and its derivatives aren''t defined at x = 0.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How do you find the series for cos²x?', 'Use cos²x = (1 + cos 2x)/2 and the series for cos 2x: 1 − x² + x⁴/3 − …', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for √(1 + x) up to x².', '1 + x/2 − x²/8.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How do you differentiate a Maclaurin series?', 'Differentiate term by term, e.g. the derivative of sin x''s series gives cos x''s series.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How can you integrate using series?', 'Integrate the series term by term, e.g. to approximate ∫ e^(−x²) dx.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the series for arctan x?', 'x − x³/3 + x⁵/5 − …, valid for |x| ≤ 1.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the general term of the eˣ series?', 'xʳ/r!.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What is the general term of the sin x series?', '(−1)ʳ x^(2r+1)/(2r + 1)!.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Why is only a finite number of terms used in practice?', 'Higher terms become very small for small x, so a few terms give a good approximation.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for tan x up to x³.', 'x + x³/3.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'How do you find the series for e^(sin x)?', 'Substitute the series for sin x into eᵘ = 1 + u + u²/2 + … and collect terms.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for sinh x.', 'x + x³/3! + x⁵/5! + …', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the Maclaurin series of ln(1 + 2x) up to x³, with its validity.', '2x − 2x² + (8/3)x³, valid for −½ < x ≤ ½.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Use the series for cos x to estimate cos 0.1.', '1 − 0.01/2 + 0.0001/24 ≈ 0.995004.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Find the series for eˣ cos x up to x³.', '(1 + x + x²/2 + x³/6)(1 − x²/2) = 1 + x − x³/3 + …', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'What must be true of f for its Maclaurin series to exist?', 'f(0), f′(0), f″(0), … must all exist and be finite.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.2', 'Series: Maclaurin & Taylor', 'Are Taylor series about x = a part of Edexcel Core Pure?', 'No. Core Pure 2 covers Maclaurin series, and Taylor series about x = a appear in the Further Pure 1 option.', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is an improper integral?', 'An integral where a limit is infinite or the integrand is undefined at a point in the range.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you evaluate ∫₁^∞ 1/x² dx?', 'lim (t→∞) [−1/x]₁ᵗ = 1.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Does ∫₁^∞ 1/x dx converge?', 'No; ln t → ∞, so it diverges.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Evaluate ∫₀¹ 1/√x dx.', '[2√x]₀¹ = 2 (the integral converges even though 1/√x is undefined at 0).', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the mean value of f(x) over [a, b]?', '(1/(b − a)) ∫ₐᵇ f(x) dx.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Find the mean value of x² over [0, 3].', '(1/3) × 9 = 3.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is ∫ 1/√(1 − x²) dx?', 'arcsin x + c.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is ∫ 1/(1 + x²) dx?', 'arctan x + c.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is ∫ 1/√(a² − x²) dx?', 'arcsin(x/a) + c.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is ∫ 1/(a² + x²) dx?', '(1/a) arctan(x/a) + c.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the derivative of arcsin x?', '1/√(1 − x²).', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the derivative of arccos x?', '−1/√(1 − x²).', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the derivative of arctan x?', '1/(1 + x²).', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Integrate 1/(x² + 4).', '(1/2) arctan(x/2) + c.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Integrate 1/√(9 − x²).', 'arcsin(x/3) + c.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you integrate 1/(x² + 2x + 5)?', 'Complete the square: (x + 1)² + 4, giving (1/2) arctan((x + 1)/2) + c.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do partial fractions help integrate 1/((x + 1)(x² + 1))?', 'Split into A/(x + 1) + (Bx + C)/(x² + 1), then integrate using ln and arctan.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the partial fraction form for (px + q)/((x − a)(x² + b²))?', 'A/(x − a) + (Bx + C)/(x² + b²).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Integrate x/(x² + 1).', '½ ln(x² + 1) + c.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you integrate 1/√(x² + a²)?', 'arsinh(x/a) + c, or ln(x + √(x² + a²)) + c.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you integrate 1/√(x² − a²)?', 'arcosh(x/a) + c, or ln(x + √(x² − a²)) + c.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is a reduction formula?', 'A formula expressing an integral Iₙ in terms of Iₙ₋₁ or Iₙ₋₂, often found using integration by parts.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Derive a reduction formula for Iₙ = ∫ xⁿ eˣ dx.', 'By parts: Iₙ = xⁿeˣ − nIₙ₋₁.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the arc length of a curve y = f(x)?', 's = ∫ √(1 + (dy/dx)²) dx.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the arc length for a parametric curve?', 's = ∫ √((dx/dt)² + (dy/dt)²) dt.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is the surface area of revolution about the x-axis?', 'S = 2π ∫ y √(1 + (dy/dx)²) dx.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Why might an improper integral diverge?', 'The area is infinite because the function doesn''t decrease fast enough, or has an infinite discontinuity.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'How do you evaluate ∫₀^∞ e^(−x) dx?', 'lim (t→∞) [−e^(−x)]₀ᵗ = 1.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What is lim (x→∞) x e^(−x)?', '0, because exponentials grow faster than polynomials.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'What substitution integrates 1/√(1 − x²) directly?', 'x = sin θ.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Find the mean value of sin x over [0, π].', '(1/π) × [−cos x] from 0 to π = 2/π.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Differentiate arcsin 2x.', '2/√(1 − 4x²).', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Evaluate the integral of x e^(−x) from 0 to ∞.', 'By parts, [−x e^(−x) − e^(−x)] from 0 to t → 1 as t → ∞, since t e^(−t) → 0.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Evaluate the integral of 1/(1 + x²) from 0 to 1.', 'arctan 1 − arctan 0 = π/4.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'Evaluate the integral of 1/√(4 − x²) from 0 to 1.', 'arcsin(1/2) − arcsin 0 = π/6.', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.3', 'Methods in Calculus', 'If f has mean value m on [a, b], what is the mean value of kf(x) + c?', 'km + c.', 36),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you find a volume of revolution for a parametric curve about the x-axis?', 'V = π ∫ y² (dx/dt) dt, with limits in t.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you find a volume about the y-axis for a parametric curve?', 'V = π ∫ x² (dy/dt) dt.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when x = t², y = 2t for 0 ≤ t ≤ 1 is rotated about the x-axis.', 'π ∫₀¹ 4t² × 2t dt = 8π × ¼ = 2π.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when x = cos t, y = sin t (0 ≤ t ≤ π) is rotated about the x-axis.', 'A sphere of radius 1: 4π/3.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Why must limits be converted to t for parametric volumes?', 'The integral is with respect to t, so the x-limits must be replaced by corresponding t-values.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can you avoid sign errors in parametric volumes?', 'Check whether x increases or decreases with t; swap limits if needed so the volume is positive.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can volumes of revolution model a wine glass?', 'By rotating a curve describing the glass''s profile, possibly in parts.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you model a composite solid?', 'Split it into sections, find the volume of each, and add.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when y = cosh x from 0 to 1 is rotated about the x-axis.', 'π ∫₀¹ cosh²x dx = (π/2)(1 + sinh 2/2) = (π/4)(2 + sinh 2).', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you rotate around a line other than an axis, e.g. y = 1?', 'Use π ∫ (y − 1)² dx, measuring the radius from the line.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can a volume of revolution be used to find the mass of an object?', 'Multiply the volume by the density.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What is the volume when the region between y = 2x and y = x² is rotated about the y-axis?', 'x = y/2 and x = √y: π ∫₀⁴ (y − y²/4) dy = π(8 − 16/3) = 8π/3.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can you check a volume of revolution answer?', 'Compare with a simple shape of similar size (cone, cylinder or sphere).', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What is the limitation of using a volume of revolution to model a bottle?', 'Real bottles have thickness, necks and non-symmetrical features.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume of y = √(sin x) from 0 to π rotated about the x-axis.', 'π ∫₀^π sin x dx = 2π.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What substitution helps find π ∫ y² dx if y = 1/√(1 + x²)?', 'π ∫ 1/(1 + x²) dx = π arctan x.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when y = 1/√(1 + x²) from 0 to 1 is rotated about the x-axis.', 'π arctan 1 = π²/4.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when y = sec x from 0 to π/4 is rotated about the x-axis.', 'π ∫ sec²x dx = π tan(π/4) = π.', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How can volumes of revolution involve integration by parts?', 'E.g. rotating y = √x eˣ requires ∫ x e^(2x) dx, which needs integration by parts.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What is the volume of a torus (doughnut)?', '2π²Rr², where R is the distance from the centre to the tube''s centre and r is the tube''s radius.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How is the volume of a region rotated 360° different from rotating by 2π?', 'They are the same: a full turn of 360° is 2π radians.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when x = t + 1, y = t² for 0 ≤ t ≤ 1 is rotated about the x-axis.', 'π ∫₀¹ t⁴ × 1 dt = π/5.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How do you find the volume when rotating about the y-axis a curve given as y = f(x)?', 'Rearrange to x = g(y) and use π ∫ [g(y)]² dy.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What is the volume of a hemispherical bowl of radius r?', '(2/3)πr³.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What happens to the volume if the curve is scaled by factor k in both directions?', 'The volume scales by k³.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'What happens to the volume if y is scaled by k?', 'The volume scales by k².', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How is Pappus''s theorem related to volumes of revolution?', 'Volume = area × distance travelled by the centroid (2π × distance to the axis).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'How is a volume of revolution calculated numerically when the integral is hard?', 'Use numerical methods such as the trapezium rule or Simpson''s rule on π y².', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Why might a model use two different curves for the inside and outside of a cup?', 'To account for the thickness of the cup''s walls.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when the region bounded by y = ln x, the y-axis, y = 0 and y = 1 is rotated about the y-axis.', 'x = eʸ, so π∫e^(2y) dy from 0 to 1 = (π/2)(e² − 1).', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'Find the volume when x = 2t, y = t² for 0 ≤ t ≤ 2 is rotated about the x-axis.', 'π∫y²(dx/dt) dt = π∫t⁴ × 2 dt from 0 to 2 = 64π/5.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.4', 'Volumes of Revolution (Core Pure + FP2)', 'The ellipse x = 3 cos t, y = 2 sin t is rotated about the x-axis. Find the volume.', 'An ellipsoid: (4/3)π × 3 × 2² = 16π.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What are polar coordinates?', 'Coordinates (r, θ), where r is the distance from the pole and θ is the angle from the initial line.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you convert polar to Cartesian?', 'x = r cos θ, y = r sin θ.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you convert Cartesian to polar?', 'r² = x² + y², tan θ = y/x (taking care with the quadrant).', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the polar equation r = a?', 'A circle with centre the pole and radius a.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the polar equation θ = α?', 'A half-line from the pole at angle α.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the curve r = aθ?', 'A spiral (Archimedean spiral).', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the curve r = a(1 + cos θ)?', 'A cardioid.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the curve r = a cos 2θ?', 'A four-petalled rose curve.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the curve r = 2a cos θ?', 'A circle through the pole, with centre (a, 0) and radius a.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the area enclosed by a polar curve?', 'A = ½ ∫ r² dθ between the limits.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Find the area enclosed by r = 2 for 0 ≤ θ ≤ 2π.', '½ ∫ 4 dθ = 4π.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Find the area of the cardioid r = 1 + cos θ.', '½ ∫₀^(2π) (1 + cos θ)² dθ = 3π/2.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you find where two polar curves intersect?', 'Set the r-values equal and solve for θ, also checking the pole.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you find a tangent parallel to the initial line?', 'Set dy/dθ = 0, where y = r sin θ.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you find a tangent perpendicular to the initial line?', 'Set dx/dθ = 0, where x = r cos θ.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Convert r = 4 sin θ to Cartesian form.', 'r² = 4r sin θ, so x² + y² = 4y (a circle centred at (0, 2)).', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Convert x² + y² = 9 to polar form.', 'r = 3.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Convert y = x to polar form.', 'θ = π/4 (and θ = −3π/4 for negative r).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Why is r usually taken as non-negative?', 'By convention r ≥ 0; values of θ that give negative r are excluded from the sketch.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What does a cardioid look like?', 'A heart shape with a cusp at the pole.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How many petals does r = cos 3θ have?', '3.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How many petals does r = cos 2θ have?', '4.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the area of one petal of r = cos 2θ?', '½ ∫ from −π/4 to π/4 of cos²2θ dθ = π/8.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What identity helps integrate r² = cos²θ?', 'cos²θ = (1 + cos 2θ)/2.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you sketch a polar curve?', 'Tabulate r for key θ values, note symmetry, and find where r = 0 and r is maximum.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What does symmetry about the initial line mean for r = f(θ)?', 'f(−θ) = f(θ), e.g. curves involving only cos θ.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'How do you find the area between two polar curves?', 'Subtract the areas: ½ ∫ (r₁² − r₂²) dθ over the appropriate range.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the maximum r of r = 3 + 2 cos θ?', '5, when θ = 0.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Does r = 3 + 2 cos θ pass through the pole?', 'No, since r ≥ 1 for all θ (a dimpled limaçon).', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What is the pole?', 'The origin in polar coordinates.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Find the area enclosed by r = 2θ for 0 ≤ θ ≤ π and the initial line.', '½∫4θ² dθ from 0 to π = 2π³/3.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'What happens where a polar curve r = f(θ) passes through the pole?', 'If f(α) = 0, the half-line θ = α is a tangent to the curve at the pole.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'For r = a(p + q cos θ) with p > q > 0, when is the curve convex?', 'Convex (egg-shaped) when p ≥ 2q and dimpled when q < p < 2q. When p = q the curve is a cardioid.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.5', 'Polar Coordinates', 'Convert r = 2 sec θ to Cartesian form.', 'r cos θ = 2, so x = 2.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the definition of sinh x?', 'sinh x = (eˣ − e^(−x))/2.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the definition of cosh x?', 'cosh x = (eˣ + e^(−x))/2.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the definition of tanh x?', 'tanh x = sinh x/cosh x = (eˣ − e^(−x))/(eˣ + e^(−x)).', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the key hyperbolic identity?', 'cosh²x − sinh²x = 1.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the range of cosh x?', 'cosh x ≥ 1.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the range of tanh x?', '−1 < tanh x < 1.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What does the graph of y = cosh x look like?', 'A U-shape (catenary) with minimum (0, 1), symmetric about the y-axis.', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What does the graph of y = sinh x look like?', 'An S-shape through the origin, increasing, and odd.', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of sinh x?', 'cosh x.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of cosh x?', 'sinh x.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of tanh x?', 'sech²x.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is Osborn''s rule?', 'To convert a trig identity to a hyperbolic one, replace cos with cosh and sin with sinh, but change the sign of any product of two sines.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is sinh 2x?', '2 sinh x cosh x.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is cosh 2x?', 'cosh²x + sinh²x = 2cosh²x − 1 = 1 + 2sinh²x.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is arsinh x in logarithmic form?', 'ln(x + √(x² + 1)).', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is arcosh x in logarithmic form?', 'ln(x + √(x² − 1)), for x ≥ 1.', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is artanh x in logarithmic form?', '½ ln((1 + x)/(1 − x)), for |x| < 1.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of arsinh x?', '1/√(x² + 1).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of arcosh x?', '1/√(x² − 1).', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is the derivative of artanh x?', '1/(1 − x²).', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Solve cosh x = 2.', 'x = ±ln(2 + √3).', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Solve sinh x = 3/4.', 'x = ln(3/4 + 5/4) = ln 2.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Solve 3 sinh x + cosh x = 3.', 'In exponentials: 3(eˣ − e^(−x))/2 + (eˣ + e^(−x))/2 = 3 → 2eˣ − e^(−x) = 3 → 2e^(2x) − 3eˣ − 1 = 0, eˣ = (3 + √17)/4, x = ln((3 + √17)/4).', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is ∫ sinh x dx?', 'cosh x + c.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is ∫ cosh x dx?', 'sinh x + c.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is ∫ tanh x dx?', 'ln cosh x + c.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is a catenary?', 'The shape of a hanging chain, described by y = a cosh(x/a).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Is cosh x even or odd?', 'Even.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Is sinh x even or odd?', 'Odd.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'What is sech x?', '1/cosh x.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'State the domain and range of arcosh x.', 'Domain x ≥ 1, range y ≥ 0 — the restriction that makes cosh one-to-one.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Prove cosh²x − sinh²x ≡ 1 from the definitions.', '[(eˣ + e^(−x))² − (eˣ − e^(−x))²]/4 = (2 + 2)/4 = 1.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Integrate 1/√(x² + 9).', 'arsinh(x/3) + c, or ln(x + √(x² + 9)) + c.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Solve 2cosh²x − 5cosh x + 2 = 0.', '(2cosh x − 1)(cosh x − 2) = 0. cosh x = ½ is impossible (cosh x ≥ 1), so cosh x = 2 and x = ±ln(2 + √3).', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.6', 'Hyperbolic Functions', 'Differentiate cosh 3x.', '3 sinh 3x.', 35),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is an integrating factor?', 'For dy/dx + P(x)y = Q(x), the integrating factor is e^(∫P dx).', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'How do you solve dy/dx + P(x)y = Q(x)?', 'Multiply by the integrating factor I: d(Iy)/dx = IQ, then integrate.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve dy/dx + 2y = e^(−x).', 'IF = e^(2x): (ye^(2x))'' = eˣ, so y = e^(−x) + Ce^(−2x).', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve x dy/dx + y = x².', '(xy)'' = x², so xy = x³/3 + C, y = x²/3 + C/x.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is a second-order linear differential equation with constant coefficients?', 'a d²y/dx² + b dy/dx + cy = f(x).', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the auxiliary equation?', 'am² + bm + c = 0.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the complementary function if the auxiliary equation has distinct real roots α, β?', 'y = Ae^(αx) + Be^(βx).', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the complementary function for a repeated root α?', 'y = (A + Bx)e^(αx).', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the complementary function for complex roots p ± qi?', 'y = e^(px)(A cos qx + B sin qx).', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the general solution of a non-homogeneous second-order ODE?', 'Complementary function + particular integral.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is a particular integral?', 'Any solution of the full equation, found by trying a function similar to f(x).', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What trial function is used for f(x) = ke^(λx)?', 'Ae^(λx) (or Axe^(λx) if λ is a root of the auxiliary equation).', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What trial function is used for f(x) = polynomial of degree n?', 'A general polynomial of degree n.', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What trial function is used for f(x) = k cos ωx?', 'A cos ωx + B sin ωx.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What happens if the trial function is part of the complementary function?', 'Multiply the trial by x (or x² for a repeated root).', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y'''' − 5y'' + 6y = 0.', 'm² − 5m + 6 = 0, m = 2, 3: y = Ae^(2x) + Be^(3x).', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y'''' + 4y = 0.', 'm = ±2i: y = A cos 2x + B sin 2x.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y'''' + 2y'' + y = 0.', 'm = −1 (repeated): y = (A + Bx)e^(−x).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Find a particular integral for y'''' − y = 2x.', 'Try y = ax + b: −ax − b = 2x, so y = −2x.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'How are boundary conditions used?', 'They determine the constants A and B, giving a particular solution.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is a homogeneous equation?', 'One where f(x) = 0.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'How do you solve simultaneous first-order DEs such as dx/dt = ax + by, dy/dt = cx + dy?', 'Differentiate one equation and substitute to get a second-order equation in one variable.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What does separating variables require?', 'The equation can be written as g(y) dy = f(x) dx.', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve dy/dx = y tan x.', 'ln|y| = −ln|cos x| + c, so y = A sec x.', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y'''' − 4y'' + 13y = 0.', 'm = 2 ± 3i: y = e^(2x)(A cos 3x + B sin 3x).', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What trial is used for y'''' + y = sin x?', 'Since sin x is in the CF, try x(A cos x + B sin x).', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What substitution can reduce a DE to separable form?', 'E.g. y = vx for homogeneous equations dy/dx = f(y/x).', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is the order of a differential equation?', 'The highest derivative that appears.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'How do you check a DE solution?', 'Differentiate and substitute back into the equation.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'What is a first-order linear DE?', 'One of the form dy/dx + P(x)y = Q(x).', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y″ − 3y′ + 2y = 4.', 'CF: m = 1, 2 gives Aeˣ + Be^(2x). PI: y = 2. General solution y = Aeˣ + Be^(2x) + 2.', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Which trial function is needed for y″ − 3y′ + 2y = e^(2x)?', 'λxe^(2x), because e^(2x) is already part of the complementary function.', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve dy/dx − y/x = x for x > 0.', 'Integrating factor 1/x: d(y/x)/dx = 1, so y/x = x + C and y = x² + Cx.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.7', 'Methods in Differential Equations', 'Solve y″ + 4y = 8 with y(0) = 0 and y′(0) = 2.', 'y = A cos 2x + B sin 2x + 2. y(0) = 0 gives A = −2, and y′(0) = 2B = 2 gives B = 1. So y = 2 − 2cos 2x + sin 2x.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is simple harmonic motion as a differential equation?', 'd²x/dt² = −ω²x.', 1),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the general solution of d²x/dt² = −ω²x?', 'x = A cos ωt + B sin ωt.', 2),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is damped harmonic motion?', 'd²x/dt² + k dx/dt + ω²x = 0, where the damping term reduces the amplitude.', 3),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is heavy damping?', 'The auxiliary equation has two distinct real (negative) roots; the system returns to equilibrium slowly without oscillating.', 4),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is critical damping?', 'The auxiliary equation has a repeated root; the system returns to equilibrium fastest without oscillating.', 5),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is light damping?', 'The auxiliary equation has complex roots; the system oscillates with decreasing amplitude.', 6),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is forced oscillation?', 'An oscillating system with an external driving force: x'''' + kx'' + ω²x = f(t).', 7),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is resonance in DEs?', 'When the driving frequency equals the natural frequency, amplitude grows (the particular integral includes t).', 8),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is population growth with limits modelled?', 'dP/dt = kP(1 − P/K), the logistic equation.', 9),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is predator–prey interaction modelled?', 'Using coupled first-order differential equations for each population.', 10),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the general strategy for coupled DEs?', 'Eliminate one variable by differentiating to give a second-order DE in the other.', 11),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What does the steady state of a model mean?', 'The long-term behaviour, e.g. when derivatives are zero.', 12),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the model for Newton''s law of cooling?', 'dT/dt = −k(T − T_s).', 13),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is a mixing problem modelled?', 'Rate of change of amount = rate in − rate out, where rate out depends on the concentration.', 14),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'Set up a DE: a tank contains 100 L of water with 10 kg salt; brine at 0.5 kg/L enters at 2 L/min and mixture leaves at 2 L/min.', 'dS/dt = 1 − 2S/100 = 1 − S/50.', 15),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the solution of dS/dt = 1 − S/50 with S(0) = 10?', 'S = 50 − 40e^(−t/50).', 16),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is air resistance included in a motion model?', 'Add a resistive term such as −kv or −kv² to the force equation.', 17),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'Solve m dv/dt = mg − kv for v with v(0) = 0.', 'v = (mg/k)(1 − e^(−kt/m)).', 18),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the terminal velocity in m dv/dt = mg − kv?', 'mg/k.', 19),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How can you evaluate a DE model?', 'Compare predictions with data, check long-term behaviour, and assess assumptions.', 20),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is the period of SHM x'''' = −ω²x?', '2π/ω.', 21),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How do you find the amplitude of x = 3 cos 2t + 4 sin 2t?', '√(9 + 16) = 5.', 22),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What does a negative coefficient in the auxiliary roots imply for long-term behaviour?', 'Solutions decay to zero (the system is stable).', 23),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What does a positive real root imply for long-term behaviour?', 'Solutions grow without limit (the system is unstable).', 24),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How is an electrical circuit modelled by a DE?', 'E.g. L d²q/dt² + R dq/dt + q/C = E(t), analogous to damped oscillation.', 25),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What is a limitation of the logistic model?', 'It assumes a constant carrying capacity and growth rate.', 26),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'In a predator–prey model, what does x'' = ax − bxy represent?', 'Prey grow at rate a and are eaten at a rate proportional to encounters xy.', 27),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How do you interpret the constants in a model?', 'Relate each to a physical quantity or rate, e.g. k as a damping coefficient.', 28),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'What does it mean if a model gives negative populations?', 'The model has broken down; it is only valid over a limited range.', 29),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'How can initial conditions be used in modelling DEs?', 'They determine the constants and give the specific solution for the situation.', 30),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'Classify the damping in x″ + 4x′ + 4x = 0.', 'm² + 4m + 4 = 0 has a repeated root −2, so the damping is critical: x = (A + Bt)e^(−2t).', 31),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'Classify and solve x″ + 2x′ + 5x = 0.', 'm = −1 ± 2i, so light damping: x = e^(−t)(A cos 2t + B sin 2t).', 32),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'Classify the damping in x″ + 5x′ + 4x = 0.', 'm = −1 or −4, two real negative roots, so heavy damping with no oscillation.', 33),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'For x″ + kx′ + 9x = 0 with k > 0, which k gives critical damping?', 'k² = 4 × 9, so k = 6.', 34),
  ('Further Mathematics', 'Edexcel', 'alevel', 'CP2.8', 'Modelling with Differential Equations', 'Turn dx/dt = 2x + y, dy/dt = x + 2y into a second-order equation in x.', 'y = dx/dt − 2x. Differentiating and substituting gives d²x/dt² − 4dx/dt + 3x = 0.', 35)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Further Mathematics' AND exam_board = 'Edexcel' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked;

COMMIT;
